INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0303', 'spa', 'Preposicion: distributivamente ''cada uno, por cabeza''; espacialmente ''entre, en medio de''; secuencialmente ''por turno''. Una preposicion griega versati', 'Preposicion: distributivamente ''cada uno, por cabeza''; espacialmente ''entre, en medio de''; secuencialmente ''por turno''. Una preposicion griega versatil que en el Nuevo Testamento lleva con mayor frecuencia una fuerza distributiva — ''cada uno'' o ''por cabeza'' — como cuando Jesus envia a los setenta y dos de ''dos en dos'' (Lc 10:1) o el amo paga a los trabajadores ''un denario cada uno'' (Mt 20:9). Tambien puede indicar posicion espacial, significando ''entre'' o ''en medio de'', como la cizana sembrada entre el trigo (Mt 13:25). En una frase especializada (ἀνὰ μέρος, 1 Co 14:27) transmite orden secuencial: ''por turno''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0304', 'spa', 'escaleras, gradas, tramo de escalones que asciende a un nivel superior', 'Este sustantivo denota un tramo de escalones o escaleras. Ambas apariciones se encuentran en Hechos 21 durante el arresto de Pablo en el templo de Jerusalén. En el versículo 35, la violencia de la multitud fue tan grande que los soldados tuvieron que cargar a Pablo ἐπὶ τοὺς ἀναβαθμούς—subiendo las escaleras—hasta el cuartel. El versículo 40 indica que Pablo, de pie ἐπὶ τῶν ἀναβαθμῶν—en las escaleras—hizo señas a la multitud pidiendo silencio. Estas escaleras conectaban los atrios del templo con la Fortaleza Antonia, la guarnición romana que dominaba el monte del templo. El detalle topográfico preciso de Lucas sitúa vívidamente la escena en la arquitectura de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0305', 'spa', 'Subir, ascender; desplazarse hacia arriba, ascender al cielo, crecer (plantas) o embarcar (en una nave).', 'ἀναβαίνω es el verbo estándar del Nuevo Testamento para el movimiento ascendente, formado transparentemente de ἀνά («arriba») y βαίνω («ir, pisar»). Su uso más frecuente refleja la topografía de la Palestina antigua: «subir» a Jerusalén, situada en las tierras altas de Judea, es la expresión habitual de peregrinación, y el verbo porta el peso teológico de acercarse a la ciudad santa de Dios. Jesús «sube» a Jerusalén repetidamente en los Evangelios (Mt 20:17-18). Pero la palabra también alcanza el cielo: Jesús asciende al Padre (Jn 20:17), y el humo y las oraciones ascienden ante el trono de Dios en Apocalipsis. Las extensiones figuradas al crecimiento vegetal (Mr 4:8) y al surgimiento mental (Lc 24:38) muestran el verbo más allá de su sentido espacial literal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0308', 'spa', 'Mirar hacia arriba o alzar la vista; recobrar o recibir la vista tras la ceguera', 'Mirar hacia arriba o alzar la vista; recobrar o recibir la vista tras la ceguera');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0312', 'spa', 'Anunciar, declarar, informar — dar a conocer proclamando noticias, eventos o revelacion divina a otros. ἀναγγέλλω lleva el peso de una comunicacion de', 'Anunciar, declarar, informar — dar a conocer proclamando noticias, eventos o revelacion divina a otros. ἀναγγέλλω lleva el peso de una comunicacion deliberada — no mera charla, sino el acto intencional de traer palabra o hacer algo publicamente conocido. En los Evangelios, Jesus promete que el Espiritu ''os anunciara las cosas que han de venir'' (Jn 16:13), dandole al verbo una dimension reveladora. En otros pasajes sirve para informar sobre eventos (Hch 14:27) o declarar verdades acerca de Dios (1 Jn 1:5). El prefijo ἀνα- (''de vuelta, hacia arriba'') senala la raiz clasica de la palabra: llevar noticias de regreso a una audiencia expectante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0313', 'spa', 'nacer de nuevo, engendrar de nuevo, regenerar espiritualmente', 'Este verbo compuesto significa engendrar o dar a luz de nuevo, usado metafóricamente para la regeneración espiritual. Pedro lo usa en 1 Pedro 1:3 para bendecir a Dios quien κατὰ τὸ πολὺ αὐτοῦ ἔλεος ἀναγεννήσας ἡμᾶς—según su gran misericordia nos ha hecho nacer de nuevo—a una esperanza viva mediante la resurrección de Cristo. El versículo 23 declara que los creyentes han nacido de nuevo (ἀναγεγεννημένοι) no de semilla corruptible sino incorruptible, mediante la palabra viva y permanente de Dios. Ambos pasajes enfatizan el nuevo nacimiento espiritual como obra de Dios, produciendo esperanza viva y vida eterna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0314', 'spa', 'Leer un texto escrito; en voz pasiva, ser leído en voz alta en un contexto público o congregacional.', 'Leer un texto escrito; en voz pasiva, ser leído en voz alta en un contexto público o congregacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0315', 'spa', 'Obligar o forzar a alguien a actuar, ya sea por autoridad, persuasion o presion externa; en pasiva, ser constreniido.', 'Verbo de compulsion fuerte, usado cuando alguien es presionado, instado o directamente forzado a actuar. Jesus obliga a sus discipulos a subir a la barca (Mt 14:22), un anfitrion insta a los invitados de los caminos a entrar (Lc 14:23), y Pablo confiesa que en otro tiempo intentaba forzar a los creyentes a blasfemar (Hch 26:11). El espanol ''obligar'' y ''forzar'' captan bien esta presion. En la voz pasiva, el termino describe a quien recibe dicha fuerza, como cuando Pablo se vio obligado a apelar al Cesar (Hch 28:19) o cuando surgio la cuestion de si Tito fue obligado a circuncidarse (Ga 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0316', 'spa', 'Necesario, esencial, indispensable; tambien de personas: cercano, intimo, unido por parentesco o amistad profunda.', 'Adjetivo derivado de ἀνάγκη (necesidad, compulsion), que expresa lo que es requerido por la naturaleza de las cosas o lo que esta unido por vinculos fuertes. Pablo lo emplea repetidamente para expresar necesidad teologica y practica: el evangelio debia ir primero a los judios (Hch 13:46), los miembros aparentemente mas debiles del cuerpo son en realidad mas necesarios (1 Co 12:22), y su permanencia en la carne es mas necesaria por el bien de los filipenses (Fil 1:24). Un segundo sentido notable aparece en Hch 10:24, donde Cornelio reune a sus amigos ''intimos'', personas ligadas a el por lazos tan fuertes como la necesidad misma. El espanol distingue ambos sentidos con claridad: ''necesario'' para lo esencial e ''intimo'' para lo cercano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0318', 'spa', 'Necesidad, compulsión, constricción; también angustia, adversidad o circunstancias extremas que obligan a actuar.', 'Necesidad, compulsión, constricción; también angustia, adversidad o circunstancias extremas que obligan a actuar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0320', 'spa', 'Lectura; lectura pública de las Escrituras o lectura privada de textos', 'Sustantivo que designa el acto de leer, especialmente en voz alta. Tras la «lectura» de la Ley y los Profetas en la sinagoga, Pablo fue invitado a hablar (Hechos 13:15). En 2 Corintios 3:14, Pablo describe un velo que permanece durante «la lectura del antiguo pacto», oscureciendo el entendimiento. A Timoteo le encarga dedicarse a la «lectura pública» de las Escrituras (1 Tim 4:13), elemento clave del culto y la enseñanza comunitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0321', 'spa', 'Conducir hacia arriba, zarpar, hacer subir; usado para viajes marítimos, movimiento ascendente, resurrección y ofrenda sacrificial', 'Conducir hacia arriba, zarpar, hacer subir; usado para viajes marítimos, movimiento ascendente, resurrección y ofrenda sacrificial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0322', 'spa', 'proclamar públicamente, nombrar oficialmente, designar o mostrar', 'Este verbo significa mostrar públicamente o designar oficialmente, usado frecuentemente para proclamar a alguien elegido para un cargo. Lucas 10:1 declara que el Señor nombró (ἀνέδειξεν) a otros setenta (y dos) y los envió de dos en dos delante de él. Hechos 1:24 registra la oración de los discípulos pidiendo al Señor que muestre (ἀνάδειξον) cuál de dos candidatos había escogido para reemplazar a Judas. El trasfondo clásico incluye exhibir señales, proclamar resultados electorales y mostrar públicamente. Ambos usos neotestamentarios involucran nombramiento divino para roles ministeriales, enfatizando la elección soberana de Dios y la designación pública de obreros para su misión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0324', 'spa', 'recibir hospitalariamente, dar la bienvenida como huésped, acoger y aceptar', 'Este verbo significa recibir o dar la bienvenida, especialmente en el sentido de hospitalidad. Hechos 28:7 describe cómo Publio, el funcionario principal de Malta, ἀναδεξάμενος ἡμᾶs—nos recibió hospitalariamente—y hospedó al grupo de náufragos de Pablo durante tres días. Hebreos 11:17 declara que Abraham, cuando fue probado, estaba ofreciendo (ἀνεδέξατο) a Isaac—aquel que había recibido las promesas estaba ofreciendo a su único hijo. El rango clásico incluye recibir huéspedes, aceptar evidencia, emprender tareas y admitir conceptos. Hechos emplea el sentido de recepción hospitalaria, mientras Hebreos lo usa para aceptar o recibir las promesas (lectura variante).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0326', 'spa', 'volver a la vida, revivir, vivir de nuevo', 'Este verbo significa volver a la vida o revivir. En Lucas 15:24, el padre celebra el regreso del pródigo: ''este hijo mío estaba muerto y ἀνέζησεν—ha vuelto a la vida''. Romanos 7:9 lo usa metafóricamente: Pablo dice que una vez estuvo vivo aparte de la ley, pero cuando vino el mandamiento, el pecado ἀνέζησεν—cobró vida—y él murió. Lucas lo usa literalmente para restauración a la vida (aunque aplicado metafóricamente al estado espiritual del hijo), mientras Pablo lo emplea figuradamente para la activación del pecado. Ambos involucran movimiento de la muerte o inactividad hacia la vida activa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0327', 'spa', 'Buscar con diligencia, rastrear, investigar cuidadosamente', 'Verbo que expresa una búsqueda diligente e intencionada. María y José «buscaron» al Jesús de doce años entre parientes y conocidos (Lucas 2:44-45). Bernabé fue a Tarso a «buscar» a Saulo tras su conversión (Hechos 11:25). El uso clásico incluye investigar causas y descubrir lo que ha pasado inadvertido. El término sugiere una búsqueda minuciosa y deliberada, no una mirada casual o superficial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0331', 'spa', 'Maldición solemne; persona o cosa consagrada a la destrucción divina; anatema.', 'Una de las palabras más intensas del vocabulario paulino, anatema designa aquello puesto bajo un decreto divino de separación total del pueblo de Dios y consagrado a la destrucción. En Romanos 9:3, Pablo expresa su disposición a ser él mismo ''anatema'' por causa de sus compatriotas israelitas. La fórmula corintia ''Jesús es anatema'' (1 Co 12:3) marca la confesión falsa por excelencia. Los conspiradores de Hechos 23:14 se comprometen ''con maldición'', revelando la dimensión de juramento vinculante que también posee este término. El peso teológico perdurable del vocablo se refleja en su adopción directa al castellano como ''anatema''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0332', 'spa', 'Obligarse bajo maldición solemne; invocar destrucción divina sobre uno mismo si se quebranta un juramento', 'Este verbo intensifica el juramento ordinario al invocar un anatema: una maldición solemne que llama al castigo divino si se viola el voto. En Marcos 14:71, la negación de Pedro alcanza su punto culminante cuando comienza «a maldecir y a jurar», poniéndose bajo anatema. Los tres pasajes de Hechos (23:12, 14, 21) describen una conspiración de más de cuarenta hombres que «se juramentaron bajo maldición» a no comer ni beber hasta haber matado a Pablo, un detalle narrativo dramático que muestra la gravedad letal de tales juramentos en el judaísmo del Segundo Templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0333', 'spa', 'observar cuidadosamente, examinar con atención, considerar reflexivamente', 'Este verbo compuesto intensifica θεωρέω, significando observar o considerar con cuidado, examinar con atención. En Hechos 17:23, Pablo dice a los atenienses que mientras ἀναθεωρῶν—observaba cuidadosamente—sus objetos de culto, encontró un altar inscrito «A UN DIOS DESCONOCIDO». Hebreos 13:7 exhorta a los lectores a recordar a sus antiguos líderes, ἀναθεωροῦντες—considerando cuidadosamente—el desenlace de su manera de vivir, e imitar su fe. Ambos contextos involucran observación atenta que llega a conclusiones: Pablo a partir de altares paganos, los lectores a partir de ejemplos fieles de líderes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0337', 'spa', 'Matar, dar muerte, ejecutar; quitar o abolir; tomar, recoger (a un niño)', 'Matar, dar muerte, ejecutar; quitar o abolir; tomar, recoger (a un niño)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0338', 'spa', 'sin culpa, inocente, sin reproche o falta', 'Este adjetivo describe a quienes no son la causa del mal y por tanto no tienen culpa. Jesús lo usa dos veces en Mateo 12, defendiendo a sus discípulos que arrancaban espigas en sábado. El versículo 5 señala que los sacerdotes que trabajan en el templo en sábado son ἀναίτιοί—sin culpa. El versículo 7 cita Oseas 6:6 («Misericordia quiero, no sacrificio») y añade que si los fariseos entendieran esto, no habrían condenado a τοὺς ἀναιτίους—los inocentes. El trasfondo clásico enfatiza estar libre de responsabilidad por el mal. Jesús lo aplica a quienes realizan actos legítimos acusados injustamente de quebrantar el sábado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0339', 'spa', 'sentarse, incorporarse a posición sentada desde estar acostado', 'Este verbo significa sentarse o incorporarse a posición sentada. Ambas apariciones describen resurrecciones. En Lucas 7:15, cuando Jesús toca el féretro y manda al hijo muerto de la viuda levantarse, ὁ νεκρὸς ἀνεκάθισεν—el muerto se incorporó—y comenzó a hablar. Hechos 9:40 registra que después de que Pedro oró sobre Tabita muerta y le mandó levantarse, ἀνεκάθισεν—ella se incorporó. El verbo captura el momento dramático cuando la quietud horizontal de la muerte da paso a la postura vertical de vida. Incorporarse se vuelve la primera señal visible de que la vida ha retornado, precediendo al habla y la restauración completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0341', 'spa', 'ser renovado, ser hecho nuevo otra vez, experimentar renovación', 'Este verbo en voz pasiva significa ser renovado o hecho nuevo otra vez. Ambas apariciones describen renovación espiritual continua. En 2 Corintios 4:16, Pablo declara que aunque el ser exterior se va desgastando, el ser interior ἀνακαινοῦται—se renueva—día tras día. Colosenses 3:10 describe a creyentes que se han vestido del nuevo ser τὸν ἀνακαινούμενον—que se va renovando—en conocimiento conforme a la imagen de su creador. Ambos enfatizan transformación progresiva: no un evento único sino renovación continua por el poder de Dios, restaurando a los creyentes hacia su imagen prevista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0342', 'spa', 'renovación, el acto o estado de ser hecho nuevo otra vez', 'Este sustantivo denota renovación o el estado de ser hecho nuevo. Romanos 12:2 exhorta a los creyentes a no conformarse a este siglo sino ser transformados por τῇ ἀνακαινώσει τοῦ νοός—la renovación de la mente—para discernir la voluntad de Dios. Tito 3:5 declara que Dios nos salvó mediante el lavamiento de la regeneración y ἀνακαινώσεως πνεύματος ἁγίου—renovación por el Espíritu Santo. Ambos pasajes describen la obra transformadora de Dios produciendo nuevo pensamiento y nueva vida. Romanos enfatiza transformación cognitiva que permite discernimiento moral; Tito enfatiza la obra regeneradora y renovadora del Espíritu en la salvación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0343', 'spa', 'descubrir, revelar, quitar un velo o cubierta para dar a conocer lo que estaba oculto', 'Este verbo significa descubrir o revelar, literal o metafóricamente, al quitar una cubierta. Segunda Corintios 3:14 afirma que el velo sobre la lectura del antiguo pacto no se levanta, porque solo en Cristo es quitado (ἀνακαλυπτόμενον—siendo descubierto). El versículo 18 declara que todos nosotros, con ἀνακεκαλυμμένῳ προσώπῳ—rostro descubierto—contemplamos como en un espejo la gloria del Señor y somos transformados. Pablo contrasta corazones velados que no pueden comprender a Moisés con rostros descubiertos que contemplan la gloria de Cristo. La remoción de la cubierta permite ver verdaderamente y, en consecuencia, ser transformados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0344', 'spa', 'Regresar, volver; desandar el camino hacia un lugar anterior', 'Compuesto de ἀνά (''de vuelta'') y κάμπτω (''doblar''), este verbo evoca la imagen de un camino que se curva de regreso sobre sí mismo. Los Magos regresan a su tierra por otro camino para evitar a Herodes (Mateo 2:12). En Lucas 10:6, Jesús instruye a los setenta y dos que si una casa no es digna, su paz ''volverá'' a ellos, una imagen vívida de la bendición que retorna como un bumerán. Pablo promete a los ancianos de Éfeso que regresará (Hechos 18:21), y los héroes de la fe en Hebreos 11:15 son elogiados por no anhelar volver al país que habían dejado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0345', 'spa', 'Reclinarse a la mesa — asumir la postura antigua de comer reclinado sobre un divano durante una comida. ἀνάκειμαι refleja uno de los marcadores cultur', 'Reclinarse a la mesa — asumir la postura antigua de comer reclinado sobre un divano durante una comida. ἀνάκειμαι refleja uno de los marcadores culturales mas vividos en los Evangelios: la practica grecorromana de reclinarse sobre divanes bajos para comer, apoyandose en el codo izquierdo mientras se comia con la mano derecha. Cada una de sus 14 apariciones en el Nuevo Testamento describe esta postura de comensalidad — desde los publicanos reclinados con Jesus (Mt 9:10) hasta los invitados a la boda en la parabola (Mt 22:10-11) y el entorno intimo de la Ultima Cena. Aunque en griego clasico la palabra podia significar ''estar dedicado'' o ''estar postrado'', el NT la restringe enteramente a la comunion de mesa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0346', 'spa', 'resumir, recapitular, reunir bajo un encabezado o punto principal', 'Este verbo compuesto significa resumir o recapitular, originalmente tomado de la práctica retórica de sintetizar argumentos. Romanos 13:9 declara que los mandamientos—"no cometerás adulterio, no matarás, no hurtarás, no codiciarás"—y cualquier otro mandamiento ἐν τῷ λόγῳ τούτῳ ἀνακεφαλαιοῦται—se resumen en esta palabra: "Amarás a tu prójimo como a ti mismo." Efesios 1:10 describe el plan de Dios de ἀνακεφαλαιώσασθαι τὰ πάντα ἐν τῷ Χριστῷ—reunir todas las cosas en Cristo, las del cielo y las de la tierra. Pablo lo usa para agrupar exhaustivamente múltiples elementos bajo un principio o persona unificadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0347', 'spa', 'Reclinarse a la mesa o hacer que alguien se recline; acostar — abarcando la postura del banquete y el cuidado tierno (ἀνακλίνω).', 'Verbo que capta la postura característica del antiguo Oriente Próximo de reclinarse para comer, usado tanto intransitiva como transitivamente. En su uso pasivo/intransitivo, los redimidos ''se reclinarán'' con los patriarcas en el banquete mesiánico (Mt 8:11; Lc 13:29). En su uso activo/causativo, describe a Jesús ordenando a las multitudes sentarse para la alimentación (Mr 6:39) y, con gran ternura, a María acostando al niño Jesús recién nacido en un pesebre (Lc 2:7). El sentido causativo del relato de la Natividad se ilumina mediante paralelos como el árabe adja''athu (''ella lo acostó'') y el hebreo hishkivah oto (''ella lo hizo recostarse'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0348', 'spa', 'Hacer retroceder, repeler; detener o frenar el movimiento; contener, impedir', 'Verbo compuesto cuyo sentido básico es empujar o impulsar algo hacia atrás. En contextos militares significa rechazar al atacante o hacer retroceder los escudos. En el ámbito náutico puede describir la acción de detener el rumbo de un navío. El uso médico incluye la regurgitación de alimentos o el efecto de un tratamiento que surte efecto. En sentido metafórico, se extiende a ser refrenado de un impulso o detenerse en medio de un discurso. La voz pasiva con frecuencia transmite la idea de ser detenido, contenido o impedido de llevar a cabo una acción prevista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0349', 'spa', 'Gritar fuertemente, dar alaridos; estallido vocal intenso, frecuentemente asociado a encuentros demoníacos o clamor de multitudes.', 'Compuesto de ἀνά (arriba) y κράζω (gritar), este verbo denota un estallido vocal súbito y enérgico, más fuerte y convulsivo que el habla ordinaria. En Marcos y Lucas aparece predominantemente en relatos de exorcismo, donde los espíritus inmundos chillan a través de sus víctimas (Mr 1:23, Lc 4:33, Lc 8:28). El grito aterrorizado de los discípulos al ver a Jesús caminando sobre el agua (Mr 6:49) y la exigencia vociferante de la multitud pidiendo a Barrabás (Lc 23:18) completan el uso neotestamentario. El español distingue bien los matices: ''gritó'' para un alarido puntual, ''clamando'' para un clamor sostenido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0350', 'spa', 'Examinar detenidamente, interrogar judicialmente o pedir cuentas; discernir la verdad, conducir una investigación legal o ejercer juicio evaluativo.', 'Examinar detenidamente, interrogar judicialmente o pedir cuentas; discernir la verdad, conducir una investigación legal o ejercer juicio evaluativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0352', 'spa', 'Enderezarse, erguirse; levantar la cabeza o el cuerpo desde una postura encorvada', 'Formado de ἀνά (''arriba'') y κύπτω (''inclinarse, agacharse''), este verbo describe el movimiento físico de alzarse desde una posición encorvada o inclinada. En Lucas 13:11, la mujer encorvada durante dieciocho años no podía «enderezarse en absoluto» hasta que Jesús la sanó. Lucas 21:28 lo emplea escatológicamente: «Erguíos y levantad vuestras cabezas, porque vuestra redención se acerca». En Juan 8:7 y 8:10, Jesús se yergue después de escribir en el suelo para dirigirse a los acusadores de la mujer, un gesto silencioso pero poderoso de atención deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0353', 'spa', 'Levantar, recoger; llevar arriba al cielo (de la ascension de Cristo); subir a bordo de un barco. Enraizado en la idea de elevar hacia arriba, este ve', 'Levantar, recoger; llevar arriba al cielo (de la ascension de Cristo); subir a bordo de un barco. Enraizado en la idea de elevar hacia arriba, este verbo abarca desde lo cotidiano hasta lo majestuoso. Su uso teologicamente mas cargado describe a Cristo siendo ''llevado arriba'' al cielo en la Ascension (Mr 16:19; Hch 1:2, 11, 22). Tambien cubre acciones practicas: recoger objetos fisicos como la armadura completa de Dios (Ef 6:13, 16) o llevar consigo a un companero de viaje (2 Ti 4:11; Hch 23:31). Lucas lo emplea ademas para subir a alguien a bordo de un barco (Hch 20:13-14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0355', 'spa', 'consumir, destruir por completo, agotar totalmente', 'Este verbo significa consumir totalmente, agotar o destruir por completo. En Lucas 9:54, Santiago y Juan le preguntan a Jesús si deben ordenar que descienda fuego del cielo y ἀναλῶσαι—consuma—la aldea samaritana inhospitalaria. Gálatas 5:15 advierte que si los creyentes se muerden y devoran unos a otros, cuidado no sea que ἀναλωθῆτε—seáis consumidos—unos por otros. El trasfondo clásico incluye gastar dinero, agotar recursos y destruir con fuego. Lucas lo usa literalmente para destrucción ígnea, Pablo metafóricamente para la autodestrucción comunitaria mediante el conflicto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0360', 'spa', 'partir, volver, levantar campamento y seguir adelante', 'Este verbo originalmente significaba desuncir o desatar, luego levantar campamento, partir o regresar. Lucas 12:36 describe siervos esperando que su señor ἀναλύσῃ—regrese—de la fiesta de bodas. Filipenses 1:23 expresa el deseo de Pablo de ἀναλῦσαι—partir—y estar con Cristo, lo cual es muchísimo mejor. El trasfondo náutico y militar implica soltar amarras de barcos o levantar campamento para moverse. Lucas lo aplica al regreso a casa, Pablo a la muerte como partida de la vida terrenal. Ambos implican movimiento de un estado a otro, ya sea retorno espacial o transición de vida a más allá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0363', 'spa', 'Recordar algo a alguien (voz activa) o traer a la propia memoria, acordarse (voz media/pasiva); evoca el recuerdo con fines de exhortación.', 'Verbo de memoria que opera en dos direcciones según la voz gramatical. En voz activa significa hacer presente algo en la mente de otra persona: Pablo envía a Timoteo para recordar a los corintios sus caminos en Cristo (1 Co 4:17). En voz media-pasiva se vuelve reflexivo: traer algo de vuelta a la propia memoria. Pedro «se acordó» de la predicción de Jesús al canto del gallo (Mr 14:72), y Hebreos 10:32 exhorta a los creyentes a recordar su perseverancia pasada en medio del sufrimiento. Las traducciones al español capturan bien ambas direcciones con «recordar» y «acordarse».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0364', 'spa', 'Remembranza, memorial; el acto de traer a la memoria, especialmente en contextos litúrgicos o sacrificiales', 'En los relatos de la Última Cena (Lucas 22:19; 1 Corintios 11:24-25), Jesús emplea este sustantivo para establecer la comida eucarística como un acto de remembranza. El griego conlleva un sentido más rico que la simple rememoración pasiva: implica un traer a la memoria activo y performativo que hace presente de nuevo el acontecimiento pasado. Hebreos 10:3 utiliza la misma palabra en dirección opuesta, señalando que los sacrificios anuales sirven como recordatorio de los pecados en vez de su eliminación. En español ''memoria/recuerdo'' y en alemán ''Erinnerung'' captan la fuerza conmemorativa del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0367', 'spa', 'Ananias -- nombre que llevan tres figuras del NT: el esposo engañoso de Safira, el discipulo de Damasco que restauro la vista a Saulo, y el sumo sacer', 'Ananias -- nombre que llevan tres figuras del NT: el esposo engañoso de Safira, el discipulo de Damasco que restauro la vista a Saulo, y el sumo sacerdote que presidio el juicio de Pablo. Ananias (Ἀνανίας), forma griega del hebreo Hananias (''el SENOR es misericordioso''), identifica a tres personas distintas en Hechos. Primero, Ananias esposo de Safira, quien mintio sobre el precio de venta de una propiedad y cayo muerto a los pies de Pedro (Hch 5:1-5). Segundo, Ananias el devoto discipulo en Damasco a quien el Senor envio para restaurar la vista de Saulo y bautizarlo (Hch 9:10-17; 22:12). Tercero, Ananias el sumo sacerdote que presidio el juicio de Pablo ante el Sanedrin y a quien Pablo reprendio duramente llamandolo ''pared blanqueada'' (Hch 23:2; 24:1). El espanol ''Ananias'' conserva el nombre para los tres referentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0372', 'spa', 'Descanso, reposo, cesación del trabajo o la aflicción; estado de refrigerio para el cuerpo o el espíritu.', 'Formado a partir de ἀνά (de nuevo) y παύω (cesar), ἀνάπαυσις denota una cesación que trae refrigerio: descanso en su sentido más pleno. Jesús lo ofrece como don a los cansados (Mt 11:29), mientras que la errancia inquieta de un espíritu inmundo que busca ἀνάπαυσις sin hallarlo proporciona un inquietante contrapunto (Mt 12:43, Lc 11:24). En Apocalipsis, el término toma dos giros notablemente distintos: los cuatro seres vivientes no tienen descanso de su adoración (Ap 4:8), y los adoradores de la bestia no tendrán descanso de su tormento (Ap 14:11). El español ''descanso'' y el francés ''repos'' transmiten la calidez de un verdadero refrigerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0373', 'spa', 'Descansar o hacer descansar; cesar del trabajo, refrescar a otro, o ser refrescado uno mismo. Un verbo de profundo consuelo entretejido en las invitac', 'Descansar o hacer descansar; cesar del trabajo, refrescar a otro, o ser refrescado uno mismo. Un verbo de profundo consuelo entretejido en las invitaciones mas tiernas del Nuevo Testamento. En Mateo 11:28, Jesus lo usa para prometer descanso a los cansados — ''Venid a mi, y yo os hare descansar'' — donde la voz activa lleva fuerza causativa: El mismo refresca al alma agobiada. En otros pasajes aparece intransitivamente, como cuando Jesus dice a los discipulos que ''descansen un poco'' (Mr 6:31), o escatologicamente, cuando los muertos bienaventurados ''descansan de sus trabajos'' (Ap 14:13). Pablo aprecia esta palabra para el refrigerio mutuo que los creyentes se brindan unos a otros (1 Co 16:18; Flm 1:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0375', 'spa', 'Enviar arriba, devolver o remitir a una autoridad superior; usado para traslados legales y el retorno de personas.', 'Compuesto de ἀνά (arriba) y πέμπω (enviar), este verbo encierra la idea fundamental de enviar a alguien hacia arriba, ya sea geográfica, social o legalmente. Todas las apariciones neotestamentarias se agrupan en contextos jurídico-jurisdiccionales. Pilato envía a Jesús a Herodes (Lc 23:7), Herodes lo devuelve (Lc 23:11, 15), y Festo remite el caso de Pablo al emperador (Hch 25:21). El envío de Onésimo de vuelta a Filemón por parte de Pablo (Flm 1:12) añade una dimensión personal. El español distingue bien los matices direccionales: ''envió'' (mandó) y ''envié de vuelta'' (devolvió).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0376', 'spa', 'lisiado, mutilado, cojo, físicamente discapacitado o impedido', 'Este adjetivo describe a quienes están físicamente mutilados, lisiados o discapacitados. Ambas apariciones se encuentran en el Evangelio de Lucas en la enseñanza de Jesús sobre la hospitalidad del banquete. Lucas 14:13 instruye que al dar un banquete, invite a los pobres, lisiados (ἀναπείρους), cojos y ciegos. El versículo 21 retrata al amo ordenando a su siervo traer a τοὺς ἀναπείρους—los lisiados—junto con los pobres, ciegos y cojos de calles y callejones. Jesús redefine radicalmente la hospitalidad: en lugar de invitar a quienes pueden corresponder, invite a quienes no pueden devolver el favor, incluyendo a los físicamente discapacitados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0377', 'spa', 'Reclinarse a la mesa en la postura antigua de comer; recostarse, sentarse a la mesa para comer.', 'Reclinarse a la mesa en la postura antigua de comer; recostarse, sentarse a la mesa para comer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0378', 'spa', 'Llenar, cumplir, completar o suplir lo que falta; verbo compuesto (ἀνά + πληρόω) que abarca desde el cumplimiento profético hasta la provisión práctica.', 'Verbo compuesto (ἀνά + πληρόω) que significa llenar lo que está deficiente o llevar algo a su plena realización. Su campo semántico abarca desde el cumplimiento profético hasta la provisión concreta. En Mateo 13:14 la profecía de Isaías «se cumple» en la dureza de oído del pueblo. Pablo lo emplea de manera concreta cuando la familia de Estéfanas «suplió» lo que faltaba por la ausencia de los corintios (1 Co 16:17), y teológicamente cuando los creyentes «cumplen» la ley de Cristo al sobrellevar las cargas unos de otros (Gá 6:2). Filipenses 2:30 elogia a Epafrodito por colmar la brecha en el servicio de los filipenses.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0379', 'spa', 'sin excusa, indefensible; moralmente sin fundamentos para justificación o defensa propia', 'Este raro adjetivo aparece solo dos veces en las cartas de Pablo, ambas en Romanos. Describe una condición moral donde alguien no tiene excusa legítima ni defensa para sus acciones. En Romanos 1:20, Pablo argumenta que la creación misma revela la naturaleza de Dios tan claramente que quienes lo rechazan quedan sin excusa. En Romanos 2:1, vuelve esto contra el moralista que juzga a otros mientras hace cosas similares. La evidencia multilingüe (español sin-excusa, francés sans-excuse, alemán ohne-Entschuldigung) captura consistentemente este sentido legal-moral de ser indefensible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0381', 'spa', 'encender, prender fuego, avivar (una llama); usado metafóricamente de Jesús prendiendo fuego en la tierra y el poder destructivo de la lengua', 'Este verbo describe el acto de encender o avivar un fuego. Jesús lo usa metafóricamente en Lucas 12:49, hablando de su misión de echar fuego sobre la tierra. Santiago 3:5 lo emplea para describir cómo la pequeña lengua enciende grandes bosques de conflicto. Mientras el griego clásico muestra un uso más amplio (sujetar, ofrecer en templos), el Nuevo Testamento lo restringe al encendido literal y metafórico del fuego. El patrón de traducción consistente entre idiomas (español enciende, francés allumer, alemán ἀνάπτει) refleja este significado enfocado de ignición y avivamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0383', 'spa', 'agitar, incitar, alborotar (una multitud); sacudir algo vigorosamente para provocar acción o emoción', 'Este verbo compuesto significa sacudir vigorosamente o agitar, especialmente aplicado a multitudes y emociones. En Marcos 15:11, los principales sacerdotes usan esta acción para incitar a la multitud contra Jesús, agitándolos para que demanden a Barrabás. Lucas 23:5 describe a los oponentes de Jesús acusándolo de alborotar al pueblo por toda Judea. El trasfondo clásico incluye sacudir objetos y blandir armas, pero el Nuevo Testamento se enfoca en la agitación social. Las glosas multilingües (español alborota/incitaron, francés exciter) enfatizan el papel del verbo en dinámicas de multitudes y disturbios públicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0385', 'spa', 'alzar, tirar hacia arriba, izar; usado para levantar objetos de pozos o recuperar cosas desde abajo', 'Este verbo describe la acción de sacar o tirar algo hacia arriba, a menudo desde una posición inferior. En Lucas 14:5, Jesús pregunta si alguien no sacaría a un hijo o buey que cayó en un pozo en sábado. Hechos 11:10 describe cómo la visión celestial que Pedro vio fue alzada nuevamente al cielo. El uso clásico incluye sacar agua, subir barcos a tierra, y extraer objetos. El Nuevo Testamento se enfoca en recuperación vertical. Las traducciones en varios idiomas (español fue-subido/lo-sacará, francés retirer/tirer) capturan consistentemente este movimiento ascendente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0386', 'spa', 'Resurrección, levantamiento; el acto de ser resucitado de entre los muertos, o figuradamente, un surgir en el destino.', 'Resurrección, levantamiento; el acto de ser resucitado de entre los muertos, o figuradamente, un surgir en el destino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0387', 'spa', 'Perturbar, agitar, trastornar; poner patas arriba o expulsar', 'Verbo que significa trastornar o causar conmoción. Los judíos de Tesalónica acusan a Pablo y Silas: «Estos que han trastornado el mundo entero también han venido acá» (Hechos 17:6). Tértulo señala a Pablo como quien «promueve sediciones» entre los judíos de todo el mundo (Hechos 21:38). Pablo confronta a los agitadores que «perturban» a los creyentes de Galacia (Gál 5:12). El uso clásico incluye desarraigar poblaciones y alterar la paz interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0390', 'spa', 'Conducirse o vivir de cierta manera; también, regresar o volver a un lugar.', 'En el Nuevo Testamento, este verbo describe predominantemente cómo una persona vive o se comporta, es decir, su modo de vida y conducta habitual. Pablo declara haberse conducido con santidad y sinceridad (2 Co 1:12), y Efesios recuerda una antigua manera de vivir gobernada por los deseos de la carne (Ef 2:3). Con menos frecuencia, el vocablo conserva su sentido clásico más antiguo de regresar físicamente o volver a un lugar, como cuando los oficiales regresan al concilio (Hch 5:22) o cuando Dios promete volver para reedificar el tabernáculo de David (Hch 15:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0391', 'spa', 'Conducta, manera de vivir, comportamiento: la forma habitual de vivir y actuar en sociedad.', 'Conducta, manera de vivir, comportamiento: la forma habitual de vivir y actuar en sociedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0393', 'spa', 'Salir, surgir o amanecer; del sol que sale literalmente, de la luz que amanece en sentido figurado, de una persona que surge de un linaje, o de Dios que hace salir el sol.', 'Un verbo enraizado en la imagen de la emergencia ascendente, que con mayor frecuencia describe el sol saliendo sobre el horizonte en su curso diario (Mt 13:6; Mr 16:2). Mateo lo aplica metafóricamente a la luz mesiánica que amanece sobre los que están en tinieblas (Mt 4:16, haciendo eco de Is 9:2), mientras que Hebreos lo usa para referirse a Cristo que «surge» de la tribu de Judá (He 7:14). En un uso causativo notable, Dios es quien «hace salir su sol» sobre malos y buenos por igual (Mt 5:45). Las traducciones al español captan bien estas distinciones: salió para la salida literal del sol, amaneció para el amanecer figurado, y ha surgido para el surgimiento genealógico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0394', 'spa', 'presentar ante, exponer para consideración, referir o comunicar (información) a alguien para revisión', 'Este verbo en voz media significa poner delante de alguien, presentar para consideración, o comunicar asuntos importantes para revisión. En Hechos 25:14, Festo presenta el caso de Pablo ante el rey Agripa. En Gálatas 2:2, Pablo describe cómo expuso su evangelio ante los apóstoles de Jerusalén en privado. El trasfondo clásico incluye atribuir crédito, referir asuntos a autoridades, y establecer dedicaciones. El Nuevo Testamento reduce esto a presentación formal de información para juicio o validación. La evidencia multilingüe (español expuso/les-expuse, francés communiquer) enfatiza la naturaleza comunicativa y consultiva de esta acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0395', 'spa', 'Salida del sol, aurora; el oriente -- la direccion o lugar donde sale el sol, tambien usado en sentido figurado. El sustantivo ἀνατολή deriva de ἀνατέ', 'Salida del sol, aurora; el oriente -- la direccion o lugar donde sale el sol, tambien usado en sentido figurado. El sustantivo ἀνατολή deriva de ἀνατέλλω (''levantarse, brotar'') y designa el lugar donde sale el sol: el oriente. En su sentido geografico predominante, orienta al lector: los magos vienen ''del oriente'' (Mt 2:1), los justos se reuniran ''del oriente y del occidente'' en el banquete mesianico (Mt 8:11), y el relampago destella ''desde el oriente'' (Mt 24:27). Pero Lucas y Apocalipsis conservan un sentido mas rico y luminoso ligado a la etimologia del vocablo: Zacarias profetiza que ''la aurora desde lo alto nos visitara'' (Lc 1:78), usando ἀνατολή como titulo mesianico que evoca al ''sol de justicia'' de Malaquias. El angel de Apocalipsis que asciende ''desde donde sale el sol'' (Ap 7:2) retiene la misma imageneria cosmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0396', 'spa', 'Volcar, derribar, trastornar; destruir o arruinar', 'Verbo que describe un vuelco violento: zozobrar embarcaciones, volcar mesas, arruinar vidas. Jesús «volcó» las mesas de los cambistas en el templo (Juan 2:15). Los falsos maestros «trastornan» hogares enteros con doctrina corrupta (Tito 1:11). Himeneo y Fileto «destruyen» la fe de algunos al afirmar que la resurrección ya ocurrió (2 Tim 2:18). El uso clásico describe con frecuencia naufragios y revueltas políticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0397', 'spa', 'Criar, nutrir, educar; llevar a alguien desde la infancia hasta la madurez mediante alimento y formación', 'Verbo que abarca todo el proceso de crianza y formación de una persona. Moisés fue «criado» en la casa de la hija del faraón y educado en la sabiduría egipcia (Hechos 7:20-21). Pablo fue «criado» en Jerusalén a los pies de Gamaliel (Hechos 22:3). En el griego clásico, el término incluye alimentar a alguien para que recupere la salud, criar ganado y educar a los hijos. Engloba tanto el sustento físico como la formación integral de la persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0398', 'spa', 'aparecer, hacerse visible, avistar; manifestarse o volverse visible después de estar oculto', 'Este verbo describe algo que entra en vista o aparece, especialmente después de estar oscurecido o distante. En Lucas 19:11, la gente pensaba que el reino de Dios estaba a punto de aparecer inmediatamente. Hechos 21:3 usa el participio para describir cómo Chipre apareció a la vista durante el viaje marítimo de Pablo. El uso clásico incluye sacar cosas a la luz, mostrar cualidades y proclamar. El Nuevo Testamento lo emplea para avistamientos visuales y apariciones escatológicas. El patrón multilingüe (español avistando/aparecer, francés apparaître) captura tanto el avistamiento náutico como el sentido más amplio de manifestación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0399', 'spa', 'Llevar hacia arriba; ofrecer (sacrificio o alabanza); cargar (pecados) sobre si mismo como sustituto. Verbo de movimiento ascendente que adquiere su p', 'Llevar hacia arriba; ofrecer (sacrificio o alabanza); cargar (pecados) sobre si mismo como sustituto. Verbo de movimiento ascendente que adquiere su peso teologico segun lo que se lleva. En contextos de adoracion significa ofrecer sacrificios o alabanzas a Dios, como en Hebreos 13:15 y 1 Pedro 2:5. Cuando se aplica a personas, describe el acto fisico de conducir a alguien a un lugar elevado, como cuando Jesus lleva a Pedro, Santiago y Juan al monte de la transfiguracion (Mt 17:1). De manera mas notable, en Hebreos 9:28 y 1 Pedro 2:24, adquiere fuerza vicaria: Cristo llevo nuestros pecados sobre la cruz. El espanol capta bien la distincion, usando ''ofrecer'' para el sacrificio y ''llevar'' para cargar el pecado, revelando la doble atraccion semantica del vocablo entre ofrenda cultual y carga sustitutiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0402', 'spa', 'Retirarse, apartarse, alejarse: dejar un lugar deliberadamente, a menudo para evitar peligro o buscar soledad.', 'Retirarse, apartarse, alejarse: dejar un lugar deliberadamente, a menudo para evitar peligro o buscar soledad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0406', 'spa', 'Andres: uno de los doce apostoles, hermano de Simon Pedro, originario de Betsaida.', 'Andres: uno de los doce apostoles, hermano de Simon Pedro, originario de Betsaida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0410', 'spa', 'Más allá de toda acusación, irreprochable; aquel contra quien no puede sostenerse cargo formal alguno.', 'Compuesto con alfa privativa (an- + egkaleō, ''presentar cargos''), ἀνέγκλητος describe a alguien contra quien ninguna acusación legal puede prosperar. Pablo lo emplea escatológicamente en 1 Corintios 1:8 — Dios presentará a los creyentes como irreprochables el día de Cristo — y con fuerza similar en Colosenses 1:22. En las Epístolas Pastorales se convierte en requisito clave para líderes eclesiásticos: los diáconos deben mostrarse intachables (1 Tim 3:10) y los ancianos irreprensibles (Tito 1:6–7). Aunque cercano en significado a ἄμεμπτος (G0273), ἀνέγκλητος posee un matiz forense más marcado, indicando que ningún fiscal podría sostener un caso contra la persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0414', 'spa', 'Más tolerable, más soportable; usado exclusivamente en las sentencias de juicio de Jesús al comparar el destino de las ciudades.', 'Adjetivo en grado comparativo que significa «más tolerable» o «más soportable», presente únicamente en las solemnes advertencias de Jesús sobre el juicio escatológico. Cada aparición en el NT sigue la misma fórmula: «será más tolerable para Sodoma (o Tiro y Sidón) en el día del juicio que para aquella ciudad». El español «más tolerable» reproduce fielmente el comparativo griego. La palabra implica que incluso el castigo de ciudades notoriamente perversas será más leve que el que aguarda a quienes rechazan el evangelio de primera mano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0417', 'spa', 'Viento — movimiento natural del aire, desde brisa suave hasta tormenta violenta; también se usa figuradamente para la inestabilidad.', 'Viento — movimiento natural del aire, desde brisa suave hasta tormenta violenta; también se usa figuradamente para la inestabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0421', 'spa', 'inescrutable, insondable, imposible de rastrear; imposible de investigar o comprender plenamente', 'Este adjetivo compuesto describe lo que no se puede investigar o rastrear. Pablo lo usa dos veces para describir misterios divinos. En Romanos 11:33, los juicios y caminos de Dios son inescrutables—más allá de la investigación humana. En Efesios 3:8, Pablo habla de predicar las riquezas inescrutables de Cristo. La palabra combina el prefijo negativo con un verbo que significa rastrear o seguir, sugiriendo algo que no deja huellas que seguir. Las traducciones multilingües (español inescrutable/inexplorables, francés inscrutable/insondable, alemán unergründlich) enfatizan consistentemente la imposibilidad de una investigación exhaustiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0423', 'spa', 'Irreprensible, intachable; que no puede ser objeto de acusación legítima ni reproche', 'Adjetivo que describe a alguien contra quien no se puede formular un cargo legítimo. Los supervisores de la iglesia deben ser «irreprensibles» (1 Tim 3:2). Las viudas inscritas para recibir ayuda deben ser «intachables» (1 Tim 5:7). Timoteo debe guardar el mandamiento «sin mancha» hasta la manifestación de Cristo (1 Tim 6:14). En el uso clásico se aplica a posiciones militares inexpugnables y a cosas perfectas o libres de objeción. El término pone énfasis en la reputación pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0424', 'spa', 'Subir, ascender; regresar o volver a un lugar anterior, especialmente en sentido geográfico ascendente', 'Verbo que expresa movimiento ascendente o retorno a un lugar previo. Jesús «subió» al monte para enseñar y sanar (Juan 6:3). Tras su conversión, Pablo no «subió» a Jerusalén de inmediato, sino que fue a Arabia (Gálatas 1:17). Más tarde «subió» a Jerusalén para ver a Pedro (Gálatas 1:18). En el griego clásico se usa para ascender montañas, subir a plataformas, regresar de la costa al interior y salir del mundo subterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0425', 'spa', 'Alivio, descanso, libertad; aflojamiento de presión o restricción, ya sea física, emocional o circunstancial.', 'Derivado de ἀνίημι (aflojar, soltar), ἄνεσις significa literalmente un aflojamiento de tensión — como soltar la cuerda de un arco tenso. En el NT abarca desde libertad física (Hch 24:23, donde Félix concede a Pablo custodia relajada) hasta alivio emocional (2 Cor 2:13, 7:5, donde Pablo no encuentra descanso para su espíritu ni su carne) y consuelo escatológico (2 Tes 1:7, prometiendo alivio a los atribulados). Pablo también lo usa en 2 Corintios 8:13 para asegurar a los corintios que su llamado a la colecta no pretende imponerles penuria. El término recorre así todo el espectro: ''libertad'' para el sentido custodial, ''alivio'' para el emocional y ''descanso'' para la quietud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0426', 'spa', 'examinar, interrogar, cuestionar rigurosamente (a menudo judicialmente, a veces bajo tortura)', 'Este verbo significa examinar de cerca o interrogar, a menudo en contextos legales. Ambas ocurrencias en Hechos 22 describen el plan del comandante romano de examinar a Pablo. El versículo 24 muestra al comandante ordenando que Pablo sea examinado mediante azotes, mientras el versículo 29 refleja su alarma al descubrir que la ciudadanía romana de Pablo haría ilegal tal examen. El uso clásico incluye examinar documentos y torturar para obtener información. El Nuevo Testamento lo restringe al interrogatorio judicial. Las traducciones (español interrogar, francés interroger, alemán ἀνετάζειν) enfatizan consistentemente el cuestionamiento investigativo, a menudo con matices coercitivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0427', 'spa', 'Sin, aparte de; preposición que expresa ausencia o carencia de algo esperado', 'Preposición que denota ausencia o separación de algo esencial o esperado. En Mateo 10:29 describe la soberana consciencia de Dios: ni un gorrión cae a tierra «sin» que el Padre lo sepa. Pedro la emplea dos veces en su primera epístola para describir el testimonio cristiano y la hospitalidad que proceden «sin» proclamación verbal (3:1) o «sin» murmuraciones (4:9). Esta palabra siempre rige genitivo y enfatiza la notable ausencia de aquello que le sigue.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0429', 'spa', 'descubrir, encontrar, localizar; hallar después de buscar o investigar', 'Este verbo compuesto significa descubrir o encontrar, a menudo después de buscar. En Lucas 2:16, los pastores encuentran a María, José y el bebé después de apresurarse a Belén. Hechos 21:4 describe al grupo de Pablo encontrando discípulos en Tiro. El uso clásico incluye descubrir hechos, ganar posesiones e inventar soluciones. El Nuevo Testamento lo usa para localizar personas después de buscar. Las glosas multilingües (español encontrando/hallaron, francés trouver) enfatizan el descubrimiento exitoso. El prefijo ἀνα- intensifica el verbo básico εὑρίσκω, sugiriendo un hallazgo completo o exitoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0430', 'spa', 'Soportar, tolerar o aguantar; en voz media, tener paciencia con alguien o resistir con firmeza bajo la adversidad.', 'Soportar, tolerar o aguantar; en voz media, tener paciencia con alguien o resistir con firmeza bajo la adversidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0433', 'spa', 'Conveniente, apropiado, decoroso; lo que resulta adecuado o propio en una situación determinada', 'Verbo que describe lo que es adecuado, propio o apropiado en contextos específicos. Pablo lo emplea en la instrucción ética sobre el lenguaje que conviene a los creyentes (Efesios 5:4) y sobre la sumisión conyugal que es «propia en el Señor» (Colosenses 3:18). En Filemón 1:8, Pablo podría ordenar lo que es «conveniente», pero elige apelar en su lugar. La palabra conlleva tanto connotaciones sociales como espirituales de lo que es decoroso y apropiado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0435', 'spa', 'Varón, hombre adulto; un hombre en contraposición a la mujer, un esposo en relación con su esposa, o genéricamente una persona', 'Ἀνήρ es el vocablo griego para ''hombre'' en sentido específicamente masculino, a diferencia de ἄνθρωπος que significa ''ser humano'' sin distinción de sexo. El Nuevo Testamento lo emplea abrumadoramente para dirigirse a o describir varones adultos: el discurso de Pedro en Pentecostés abre con ἄνδρες Ἰσραηλῖται, «Varones israelitas» (Hch 2:22), y Lucas salpica su narrativa con ἄνδρες más un gentilicio como forma de tratamiento formal. Su segundo uso como ''esposo'' surge naturalmente de la misma raíz semántica, especialmente en los códigos domésticos paulinos (Ef 5:22-25) y las discusiones sobre la ley matrimonial (Ro 7:2-3). El raro uso genérico de persona en Stg 1:20 muestra la palabra en el límite de su campo semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0436', 'spa', 'Resistir, oponerse, hacer frente: plantarse contra un adversario, ya sea humano, espiritual o divino.', 'Resistir, oponerse, hacer frente: plantarse contra un adversario, ya sea humano, espiritual o divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0438', 'spa', 'Flor, floración; el brote de una planta, usado metafóricamente para la fugacidad de la vida humana', 'El griego ἄνθος designa la flor o el brote de una planta, y en todas sus apariciones neotestamentarias figura en contextos metafóricos sobre la brevedad de la gloria humana. Santiago 1:10-11 compara al rico con una flor silvestre que se marchita bajo el sol abrasador, mientras que 1 Pedro 1:24 cita Isaías 40:6-8, declarando que toda carne es como hierba y su gloria como la flor del campo. La evidencia interlingüística es notablemente uniforme: español ''flor'', alemán ''Blume'' y francés ''fleur'' la traducen directamente como ''flor'', confirmando un único sentido botánico empleado metafóricamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0439', 'spa', 'fuego de carbón, brasas ardientes, lecho de carbones calientes; fuego hecho de carbón en lugar de leña', 'Este sustantivo designa un tipo específico de fuego—uno hecho de carbón o brasas ardientes en lugar de llamas de leña. Ambas ocurrencias en el Nuevo Testamento aparecen en el Evangelio de Juan. En Juan 18:18, los siervos y oficiales se calientan junto a un fuego de carbón durante el juicio de Jesús, donde Pedro lo niega. En Juan 21:9, el Jesús resucitado ha preparado un fuego de carbón en la playa para desayunar con los discípulos—el escenario donde Pedro es restaurado. La repetición de este término específico crea un eco literario que conecta la negación y restauración de Pedro. Las traducciones (español brasas/fuego-de-carbón, francés brasier, alemán Kohlenfeuer) distinguen esto del fuego ordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0441', 'spa', 'complacientes de hombres, los que buscan agradar a las personas en lugar de a Dios; quien sirve para obtener favor humano', 'Este sustantivo compuesto describe a personas que sirven para agradar a los humanos en lugar de a Dios. Pablo lo usa en pasajes paralelos dirigidos a esclavos: Efesios 6:6 y Colosenses 3:22. En ambos contextos, contrasta el servicio superficial hecho ante los ojos para agradar a los amos con el servicio sincero hecho para Cristo. El término lleva connotación negativa—implica manipulación o falta de sinceridad en el servicio motivado por aprobación humana en lugar de llamado divino. Las traducciones (español agradadores-de-hombres, alemán menschengefaellig) capturan el sentido peyorativo de adulación servil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0442', 'spa', 'Humano, perteneciente a la humanidad; propio de las personas en contraposición a lo divino o lo animal.', 'Adjetivo que significa «humano» o «propio de la humanidad», empleado para distinguir lo que pertenece al ámbito de la experiencia humana de lo que es divino, sobrenatural o meramente natural. Pablo lo usa con frecuencia: en 1 Co 10:13, la tranquilizadora afirmación de que la tentación es «común al hombre» (humana, no más allá de lo soportable); en 1 Co 2:13, la sabiduría enseñada no con palabras «humanas» sino por el Espíritu. En Ro 6:19 Pablo se disculpa por hablar «en términos humanos» a causa de la debilidad de sus oyentes. El español «humano/humana» refleja con exactitud esta esfera limitada pero comprensible de lo propiamente humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0443', 'spa', 'Homicida, asesino de seres humanos; quien quita la vida a personas', 'Este sustantivo compuesto designa a una persona que mata a otros seres humanos. Jesús lo emplea para describir al diablo, llamándolo «homicida desde el principio» (Juan 8:44), vinculando la naturaleza mortífera de Satanás con su carácter esencial. La primera epístola de Juan lo utiliza dos veces para describir el estado espiritual de quienes odian a sus hermanos: tal odio constituye un homicidio espiritual que excluye de la vida eterna (1 Juan 3:15). La palabra combina ἄνθρωπος (''ser humano'') y κτόνος (''matador''), haciendo explícito el objeto de la violencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0444', 'spa', 'Ser humano, persona; colectivamente, gente o humanidad — el término griego estándar para un miembro de la raza humana', 'El sustantivo más frecuente del Nuevo Testamento después de θεός, ἄνθρωπος cubre toda la gama de referencia humana: un individuo específico («vino un hombre»), una persona indefinida («si alguno»), y la humanidad colectivamente («los hijos de los hombres»). Aparece con frecuencia en la autodesignación de Jesús «Hijo del Hombre» (ὁ υἱὸς τοῦ ἀνθρώπου) y en declaraciones universales sobre la condición humana (Mt 4:4, «No solo de pan vivirá el hombre»). Todas las principales tradiciones traductoras emplean su término genérico para ser humano —español ''hombre'', francés ''homme'', alemán ''Mensch''—, aunque el sentido colectivo a menudo requiere un cambio al plural en las lenguas de destino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0445', 'spa', 'ejercer el cargo de procónsul, gobernar una provincia como procónsul', 'Verbo que designa el ejercicio del cargo de procónsul, un puesto específico de la administración romana. Los procónsules eran excónsules que gobernaban las provincias senatoriales con imperium, es decir, la autoridad legal para ejercer el mando. Este término técnico-administrativo refleja la realidad política del Imperio Romano en cuyo contexto surgió el cristianismo primitivo. El verbo capta la acción concreta de ejercer esta forma particular de gobernación provincial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0446', 'spa', 'Procónsul; gobernador romano de una provincia senatorial, la máxima autoridad civil en regiones como Chipre y Acaya.', 'Préstamo directo del latín pro consule, ἀνθύπατος designa al gobernador de una provincia senatorial romana, a diferencia de un legado imperial. Lucas emplea este título con notable precisión en Hechos. Sergio Paulo es el procónsul de Chipre a quien Pablo y Bernabé encuentran (Hch 13:7–8, 12), y Galión ejerce como procónsul de Acaya ante quien Pablo es llevado en Corinto (Hch 18:12). El plural en Hechos 19:38 resulta llamativo: el escribano de Éfeso dice a la turba que, si tienen queja, ''los procónsules están disponibles'' — probablemente un plural genérico referido al cargo y no a múltiples titulares simultáneos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0447', 'spa', 'soltar, liberar, dejar ir; aflojar la restricción o abandonar, renunciar', 'Este verbo expresa la idea central de soltar o liberar lo que está sujeto con firmeza. En Hechos 16:26, un terremoto desata las cadenas de los prisioneros; en Hechos 27:40, los marineros sueltan las anclas. Efesios 6:9 lo emplea en sentido figurado: se exhorta a los amos a «dejar» las amenazas. Hebreos 13:5 cita la promesa divina «no te dejaré ni te desampararé». El campo semántico abarca desde el desatamiento físico hasta el abandono metafórico, captado tanto por el español ''soltar/dejar'' como por el alemán ''nachlassen''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0449', 'spa', 'sin lavar (manos), no purificadas ritualmente; ceremonialmente impuras por falta de lavamiento', 'Este adjetivo describe manos que no han sido lavadas, específicamente en el contexto de la pureza ritual. Mateo 15:20 y Marcos 7:2 abordan la controversia farisaica sobre comer con manos sin lavar. Jesús defiende a Sus discípulos contra acusaciones de que violan la tradición al no realizar el lavamiento ceremonial de manos antes de las comidas. El asunto no es la higiene sino la observancia ritual. El uso clásico incluye manos sin lavar ofrecidas a Zeus y manchas que no pueden lavarse. El Nuevo Testamento lo restringe a debates sobre lavamiento ceremonial. Las traducciones (español sin-lavar/con-no-lavadas, francés mains-non-lavées) enfatizan la omisión ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0450', 'spa', 'Levantarse o ponerse de pie físicamente; resucitar de entre los muertos; causativamente, levantar a alguien de la muerte o a una posición de prominencia', 'Uno de los verbos con mayor carga teológica del Nuevo Testamento, que abarca desde el acto ordinario de ponerse de pie hasta el acontecimiento extraordinario de la resurrección de entre los muertos. En la narrativa cotidiana describe el levantarse para ir a algún lugar: Mateo se levanta de su mesa de impuestos (Mt 9:9), Jesús se levanta para partir de una región (Mc 10:1). Pero sus usos más trascendentales conciernen a la resurrección: Jesús predice repetidamente que resucitará al tercer día (Mc 8:31; 9:31), y se dice que Dios lo levantó de entre los muertos (Hch 2:24). El sentido transitivo causativo —levantar a alguien— se extiende a Dios suscitando profetas y líderes (Hch 3:22; 7:37). El español distingue con claridad entre levantarse (ponerse de pie) y resucitar (volver a la vida), haciendo visible la división semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0452', 'spa', 'Anás; sumo sacerdote judío, suegro de Caifás, prominente en el juicio de Jesús y el período de la iglesia primitiva', 'Anás (del hebreo Janán, que significa ''misericordioso'') ejerció como sumo sacerdote aproximadamente entre los años 6 y 15 d.C., pero conservó una enorme influencia mucho después de su destitución formal por Roma. Lucas 3:2 nombra inusualmente a Anás y Caifás como sumos sacerdotes, reflejando la autoridad de facto de Anás. Juan 18:13-24 relata que Jesús fue llevado primero ante Anás antes de ser enviado a Caifás, y Hechos 4:6 incluye a Anás entre quienes interrogaron a Pedro y Juan. Las variantes en distintos idiomas — español ''Anás'', francés ''Anne/Hannas'', alemán ''Hannas'' — señalan todas al mismo personaje histórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0453', 'spa', 'Insensato, necio, falto de entendimiento; describe a quienes no logran percibir la verdad espiritual o moral.', 'Adjetivo que significa «sin entendimiento» (de ἀ-νόητος, ''que no percibe con la mente''), y describe un fallo de percepción espiritual o intelectual, no mera ignorancia. Jesús lo emplea con fuerza en el camino a Emaús: «¡Oh insensatos, tardos de corazón para creer!» (Lc 24:25). Pablo lo dirige con igual vigor a los gálatas, que habiendo comenzado por el Espíritu retrocedieron a la carne (Gá 3:1, 3). La palabra implica una falta culpable de comprensión de lo que debería ser evidente, tal como transmite el español «insensatos».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0454', 'spa', 'locura, insensatez, demencia; falta de entendimiento o comportamiento irracional', 'Este sustantivo describe el estado de ser insensato o necio, a veces intensificándose hasta la demencia. Lucas 6:11 lo usa para describir la furia irracional de los escribas y fariseos después de que Jesús sana en el día de reposo—fueron llenos de locura. En 2 Timoteo 3:9, Pablo predice que la necedad de los falsos maestros se manifestará a todos. El uso clásico distinguía la necedad de la locura absoluta, aunque había superposición. El Nuevo Testamento lo usa tanto para la ira irracional como para la necedad manifiesta. Las traducciones (español locura/insensatez, francés folie, alemán Unverstand) abarcan el rango desde necedad hasta demencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0455', 'spa', 'Abrir o ser abierto; de puertas, ojos, bocas, sellos y cielos — en usos activos, pasivos y estativos.', 'El griego ἀνοίγω es el verbo estándar para abrir en todo el Nuevo Testamento, aplicado tanto a objetos físicos (puertas, libros, sepulcros) como a aperturas metafóricas (ojos, bocas, cielos). El español distingue «abrió» (activo) de «fue abierto» (pasivo), revelando distinciones de voz que el inglés a menudo aplana. La palabra adquiere un peso teológico especial cuando los cielos son «abiertos» (Mt 3:16, en el bautismo de Jesús) o cuando los sellos del rollo se abren en Apocalipsis. El participio perfecto crea un sentido estativo distintivo — algo que permanece abierto como resultado de una acción previa — como el cielo abierto de Jn 1:51.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0456', 'spa', 'reedificaré, volveré a edificar; reconstruir lo que ha caído o sido destruido', 'Este verbo compuesto significa edificar de nuevo o reedificar. Aparece dos veces en Hechos 15:16, ambas ocurrencias en la cita de Jacobo de Amós 9:11 durante el Concilio de Jerusalén. Jacobo cita la promesa de Dios de reedificar el tabernáculo caído de David—interpretado como la inclusión de los gentiles en el pueblo de Dios. El uso clásico incluye edificar riberas de ríos con ladrillos y reconstruir ciudades y murallas. El Nuevo Testamento lo restringe a esta única cita profética sobre restauración. La forma futura ἀνοικοδομήσω enfatiza la acción prometida de Dios de restaurar lo que ha caído.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0458', 'spa', 'Iniquidad, maldad; el estado de actuar en desafío a la ley divina o moral; transgresión de la ley.', 'Iniquidad, maldad; el estado de actuar en desafío a la ley divina o moral; transgresión de la ley.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0459', 'spa', 'Inicuo, sin ley; fuera de la Ley mosaica -- que describe transgresion moral o situacion relacional al margen de la Torah. En el Nuevo Testamento, ἄνομ', 'Inicuo, sin ley; fuera de la Ley mosaica -- que describe transgresion moral o situacion relacional al margen de la Torah. En el Nuevo Testamento, ἄνομος tiene dos matices distintos segun el contexto. Cuando se aplica a malhechores o al escatologico ''Inicuo'' (2 Ts 2:8), denota depravacion moral y transgresion deliberada de la ley divina, como cuando Jesus fue ''contado entre los inicuos'' en su crucifixion (Mr 15:28; Lc 22:37). Pero Pablo reutiliza la palabra en 1 Corintios 9:21 para describir a los gentiles que simplemente no poseen la Torah, usandola cuatro veces sin fuerza peyorativa. El espanol refleja esta division con claridad: ''inicuo'' (malvado) para el sentido 1, ''sin ley'' (sin Torah) para el sentido 2.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0460', 'spa', 'sin ley, aparte de la ley; en estado de no tener o no seguir la ley (mosaica)', 'Este adverbio describe la condición de estar sin ley, específicamente la ley mosaica en el uso paulino. Ambas ocurrencias están en Romanos 2:12, donde Pablo establece el principio de que aquellos que pecaron sin la ley perecerán sin la ley, mientras que aquellos bajo la ley serán juzgados por ella. El término indica a los gentiles que no poseen la Torá, contrastados con los judíos que sí la tienen. El uso clásico significaba ilegalmente o sin ley musical (armonía). El uso teológico del Nuevo Testamento se enfoca en la relación con la revelación mosaica. El alemán ohne-Gesetz y el español sin-ley capturan el sentido de ''sin-ley''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0461', 'spa', 'Enderezar, restaurar, levantar; devolver algo o alguien a su estado debido', 'Este verbo significa volver a poner algo en posición recta o restaurarlo a su condición apropiada. Lucas lo usa literalmente cuando Jesús «enderezó» a la mujer encorvada en la sinagoga (13:13). Santiago cita a Amós sobre Dios «reconstruyendo» el tabernáculo caído de David (Hechos 15:16), aplicando el lenguaje de restauración a la inclusión de los gentiles. Hebreos 12:12 exhorta a los creyentes a «fortalecer» las manos caídas y las rodillas debilitadas. La palabra abarca sanidad física, reconstrucción material y fortalecimiento espiritual, todas ellas formas de restauración al estado que corresponde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0462', 'spa', 'impío, profano, irreverente; que carece de reverencia o viola límites sagrados', 'Este adjetivo describe lo que es impío o profano, careciendo de la debida reverencia hacia las cosas sagradas. Ambas ocurrencias aparecen en las Epístolas Pastorales describiendo tipos de personas. En 1 Timoteo 1:9, la ley existe para los impíos y profanos entre otras categorías de pecadores. En 2 Timoteo 3:2, Pablo predice que en los últimos días la gente será impía entre otros vicios. El uso clásico describía cadáveres privados de ritos apropiados, cosas sagradas profanadas, o acciones impías. El Nuevo Testamento lo aplica al carácter moral-religioso. Las traducciones (español impíos/profanos, francés ἀνοσίοις, alemán unheilig) enfatizan la violación de la santidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0463', 'spa', 'clemencia, tolerancia, paciencia; la retención paciente de Dios del juicio merecido', 'Este sustantivo describe la clemencia o paciencia contenida, especialmente del castigo merecido. Ambas ocurrencias aparecen en Romanos describiendo el carácter de Dios. En Romanos 2:4, Pablo pregunta si la gente menosprecia las riquezas de la bondad, clemencia y paciencia de Dios. En Romanos 3:26, Pablo explica que la clemencia de Dios al pasar por alto los pecados anteriores demostró Su justicia. El uso clásico incluía armisticio, demora y alivio de enfermedad. El Nuevo Testamento lo restringe a la clemencia divina. Las traducciones (español paciencia, francés patience, alemán Geduld) enfatizan la paciencia contenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0465', 'spa', 'intercambio, algo dado en intercambio; lo que se ofrece o recibe como comercio equivalente', 'Este sustantivo describe lo que se da o recibe en intercambio por otra cosa. Ambas ocurrencias aparecen en pasajes paralelos de los Evangelios donde Jesús pregunta qué podría dar una persona en intercambio por su alma. Mateo 16:26 y Marcos 8:37 ambos plantean esta pregunta retórica después de enseñar sobre ganar el mundo entero pero perder la vida propia. El uso clásico incluía intercambios dados por amistad. El Nuevo Testamento lo restringe al dicho de Jesús sobre el valor incomparable del alma. Las traducciones (español en-cambio/en-intercambio, francés échange) enfatizan el concepto de transacción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0467', 'spa', 'Retribuir, recompensar, devolver en correspondencia; en voz pasiva: ser retribuido o recompensado', 'Verbo compuesto (ἀντί + ἀπό + δίδωμι, «devolver en retorno contra») que expresa una retribución o recompensa plena. Pablo cita Deuteronomio 32:35 en Romanos 12:19: «Mía es la venganza, yo retribuiré, dice el Señor», empleando este vocablo para el ajuste definitivo de cuentas por parte de Dios. Sin embargo, el mismo verbo porta gracia: en Lucas 14:14 Jesús promete que la generosidad hacia los pobres será recompensada en la resurrección de los justos. Pablo también lo usa en la tierna pregunta de Romanos 11:35: ¿quién le ha dado primero a Dios para que le sea devuelto? El término abarca así tanto el juicio divino como la generosidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0468', 'spa', 'pago, recompensa, retribución; lo que se devuelve, ya sea galardón o castigo', 'Este sustantivo describe el pago o retribución, usado tanto para recompensa positiva como retribución negativa. En Lucas 14:12, Jesús aconseja no invitar a quienes pueden devolver el favor, para que recibas recompensa en la resurrección. Romanos 11:9 cita los Salmos sobre las mesas de los enemigos convirtiéndose en retribución. El término es neutral respecto a lo positivo o negativo—el contexto determina si es galardón o castigo. Las traducciones (español recompensa/retribución, francés récompense, alemán Vergeltung) a veces distinguen galardón de retribución, aunque el término griego cubre ambos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0470', 'spa', 'replicar, responder (especialmente en réplica o argumento); corresponder a', 'Este verbo compuesto intensifica el simple ''responder'' (ἀποκρίνομαι) con el prefijo ἀντα- (''de vuelta, contra''), sugiriendo una respuesta que retrocede o argumenta. La palabra aparece dos veces en el Nuevo Testamento, ambas veces en contextos donde responder sería inapropiado o imposible. En Lucas 14:6, los oponentes de Jesús ''no pudieron replicar'' respecto a su sanidad en sábado. En Romanos 9:20, Pablo desafía: ''¿Quién eres tú, ser humano, para replicar a Dios?'' La evidencia multilingüe (español ''responder contra'', francés ''répondre'') captura la fuerza ligeramente oposicional que distingue esto de responder ordinariamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0471', 'spa', 'contradecir, hablar en contra, oponerse de palabra o con argumentos', 'Forma aorista (sin tiempo presente en uso) que significa hablar en oposición o responder con objeción. El verbo aparece con objeto en dativo para indicar que se habla en contra de alguien o algo, o con frase preposicional con el mismo propósito. Puede significar oponerse o contradecir, defender a alguien con la palabra, o simplemente pronunciar una réplica. Un uso especializado implica argumentar a favor y en contra de una cuestión en un debate. También puede conllevar el sentido negativo de difamar a alguien como respuesta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0472', 'spa', 'aferrarse firmemente a, adherirse a, ser devoto de; sostener o ayudar a alguien necesitado', 'En voz media, este verbo expresa un apego firme o una devoción leal. Jesús lo utiliza en el Sermón del Monte (Mateo 6:24) y su paralelo lucano (Lucas 16:13) para describir la imposibilidad de servir a dos señores: a uno se amará y al otro se despreciará; a uno se aferrará y al otro se descuidará. En 1 Tesalonicenses 5:14, Pablo exhorta a la comunidad a «sostenerse firmemente» junto a los débiles, mientras que Tito 1:9 requiere que los ancianos se aferren a la palabra fiel. El español ''aferrarse/adherirse'' y el francés ''s''attacher'' captan con precisión la cualidad tenaz de este apego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0473', 'spa', 'En lugar de, en vez de, a cambio de; porque, por causa de; sobre (acumulación)', 'En lugar de, en vez de, a cambio de; porque, por causa de; sobre (acumulación)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0476', 'spa', 'Adversario u oponente, especialmente en un litigio legal; por extensión, cualquier acusador hostil o enemigo.', 'En el griego clásico esta palabra designaba al oponente legal — ya fuera demandante o demandado en un pleito. El Nuevo Testamento conserva este sabor forense en la parábola de Jesús sobre llegar a un acuerdo con el adversario de camino al juez (Mt 5:25; Lc 12:58), mientras que la insistente súplica de la viuda contra su adversario (Lc 18:3) muestra un uso más amplio referido a alguien que causa daño. La aplicación que Pedro hace al diablo como león rugiente (1 Pe 5:8) eleva el término a una enemistad de dimensión cósmica. El vocablo abarca así desde el litigante concreto hasta el enemigo espiritual por excelencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0480', 'spa', 'Oponerse, estar en contra, actuar como adversario; mantenerse en oposición hostil contra alguien o algo.', 'Un verbo en voz media/pasiva que significa «estar en contra» u «oponerse», usado en el Nuevo Testamento para quienes resisten activamente los propósitos de Dios o a su pueblo. Los adversarios de Jesús son «avergonzados» (Lc 13:17), y él promete una sabiduría que ningún adversario podrá resistir (Lc 21:15). Pablo encuentra en Éfeso «una puerta grande y eficaz» junto con «muchos adversarios» (1 Co 16:9). El término también describe conflicto espiritual interno: la carne y el Espíritu «se oponen entre sí» (Gá 5:17). En las Pastorales caracteriza fuerzas hostiles dispuestas contra la sana doctrina (1 Ti 1:10; 5:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0482', 'spa', 'Socorrer, ayudar, asistir; asir a alguien para sostenerlo o apoyarlo', 'Este verbo en voz media significa agarrar algo o a alguien para prestarle ayuda. En el Magnificat, María celebra cómo Dios «socorrió» a Israel su siervo, acordándose de su misericordia (Lucas 1:54). Pablo cita la enseñanza de Jesús de que es más bienaventurado dar que recibir, y que se debe «ayudar» a los débiles (Hechos 20:35). En 1 Timoteo 6:2, los esclavos creyentes deben servir bien a los amos que «reciben» su buen servicio como hermanos en la fe. El sentido clásico de «asir» evoluciona hacia la idea de tomar a alguien de la mano para socorrerlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0483', 'spa', 'Hablar en contra, contradecir, negar; pasivo: ser contradicho, ser objeto de oposicion o disputa. El verbo griego ἀντιλέγω combina ἀντί (''contra'') con', 'Hablar en contra, contradecir, negar; pasivo: ser contradicho, ser objeto de oposicion o disputa. El verbo griego ἀντιλέγω combina ἀντί (''contra'') con λέγω (''hablar''), produciendo una palabra que capta la oposicion verbal en ambas direcciones. En voz activa significa contradecir, negar u objetar: los judios en Antioquia contradicen la predicacion de Pablo (Hch 13:45), o Pilato es advertido de que liberar a Jesus equivale a ''hablar contra Cesar'' (Jn 19:12). La voz pasiva conlleva un peso mas conmovedor: Simeon profetiza que el nino Jesus sera ''senal de contradiccion'' (Lc 2:34), y Pablo en Roma reconoce que ''esta secta es contradicha en todas partes'' (Hch 28:22). El espanol ''contradecir'' refleja fielmente la estructura compuesta ''hablar en contra''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0485', 'spa', 'disputa, contradicción, oposición; rebelión u hostilidad expresada mediante resistencia verbal o activa', 'Formado a partir de ἀντί (''contra'') y λόγος (''palabra/discurso''), este sustantivo denota fundamentalmente hablar en contra o contradecir. Hebreos lo emplea en dos argumentos teológicos: 6:16 señala que un juramento pone fin a toda controversia, y 7:7 afirma que sin contradicción el menor es bendecido por el mayor. Hebreos 12:3 intensifica el significado al describir la «oposición» que Jesús soportó de parte de los pecadores. Judas 1:11 invoca la «rebelión de Coré» como modelo de resistencia desafiante contra el orden establecido por Dios. La trayectoria semántica va de la disputa verbal a la rebelión activa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0489', 'spa', 'recompensa, retribución, intercambio; lo que se devuelve como respuesta mutua o a cambio', 'Este sustantivo describe la recompensa o el intercambio dado en retribución. Ambas apariciones se encuentran en las cartas de Pablo. Romanos 1:27 habla de recibir en sí mismos la recompensa debida por su error, probablemente refiriéndose a las consecuencias de la inmoralidad sexual. En 2 Corintios 6:13, Pablo solicita una recompensa de los corintios, pidiéndoles que ensanchen sus corazones en correspondencia a su afecto. El término indica intercambio mutuo o retribución apropiada. Las traducciones utilizan uniformemente vocabulario de recompensa o retribución (español recompensa, francés récompense, alemán Vergeltung).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0490', 'spa', 'Antioquía — nombre de ciudad que se refiere a Antioquía de Siria o a Antioquía de Pisidia.', 'Antioquía — nombre de ciudad que se refiere a Antioquía de Siria o a Antioquía de Pisidia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0492', 'spa', 'pasar al lado opuesto, evitar cruzándose; evadir deliberadamente a alguien tomando otra ruta', 'Este verbo compuesto significa pasar al lado opuesto, evitando deliberadamente a alguien. Ambas apariciones se encuentran en la parábola del buen samaritano de Jesús. Lucas 10:31 describe al sacerdote pasando al lado opuesto, y el versículo 32 cuenta cómo el levita hizo lo mismo. La construcción compuesta enfatiza el cruce al otro lado para evitar al hombre herido. El uso clásico incluía venir en ayuda contra un enemigo y penetrar a través. El Nuevo Testamento lo restringe a esta parábola sobre evitar involucrarse. Todas las traducciones enfatizan el cruce deliberado al otro lado para evitar el contacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0498', 'spa', 'Oponerse, resistir; disponerse en contra de una autoridad o persona con hostilidad deliberada.', 'Derivado de una metáfora militar de disponer tropas en formación de batalla contra el enemigo, este verbo en el Nuevo Testamento describe consistentemente la resistencia a la autoridad o a Dios mismo. Santiago cita dos veces Proverbios 3:34 — ''Dios resiste a los soberbios'' (Stg 4:6; 1 Pe 5:5) — donde la voz media capta la naturaleza personal y deliberada de la resistencia divina. Pablo advierte que oponerse a las autoridades gobernantes equivale a resistir la ordenanza de Dios (Ro 13:2). El término transmite una oposición enérgica e intencional, no mera pasividad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0499', 'spa', 'antitipo, figura correspondiente, copia; algo que corresponde o representa un patrón o realidad previa', 'Este adjetivo describe algo que corresponde a un patrón original: un antitipo a un tipo. Hebreos 9:24 contrasta lugares santos terrenales hechos con manos con los verdaderos celestiales, llamando a los terrenales antitipos. 1 Pedro 3:21 llama al bautismo un antitipo que corresponde a la salvación del arca de Noé. El uso clásico incluía eco, reflejo, falsificación y afecto correspondiente. El Nuevo Testamento lo usa para copias terrenales que apuntan a realidades celestiales. El alemán Gegenbild (contra-imagen) captura el concepto de representación correspondiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0500', 'spa', 'Anticristo: quien se opone a Cristo o pretende sustituirlo falsamente; engañador que niega al Padre y al Hijo.', 'Exclusivo de las epístolas juaninas, este término compuesto (ἀντί + χριστός) designa no solo a un opositor de Cristo, sino a un impostor que pretende reemplazarlo: alguien que niega la encarnación y la relación Padre-Hijo. Juan advierte que ya han surgido muchos anticristos (1 Jn 2:18), identificando como «el anticristo» a todo aquel que niega que Jesús es el Cristo (1 Jn 2:22). El vocablo funciona tanto como figura escatológica específica como categoría que abarca a engañadores presentes (2 Jn 1:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0501', 'spa', 'sacar agua de un pozo o recipiente', 'Las cuatro apariciones de este verbo en el NT se encuentran en el Evangelio de Juan, siempre en relación con el agua. En las bodas de Caná (Juan 2:8-9), los sirvientes sacan agua que ha sido transformada en vino. En el encuentro de Jesús con la mujer samaritana (Juan 4:7, 15), el acto de sacar agua del pozo de Jacob se convierte en la ocasión para un discurso sobre el agua viva. El verbo es directamente práctico — el español ''sacar'', el francés ''puiser'' y el alemán ''schöpfen'' denotan la acción cotidiana de extraer agua — sin embargo, Juan lo sitúa consistentemente en contextos donde el agua ordinaria apunta a algo extraordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0504', 'spa', 'sin agua, seco, árido; que carece de agua, usado para lugares desolados y metafóricamente para agentes espiritualmente estériles', 'Formado a partir de la alfa privativa y ὕδωρ (''agua''), este adjetivo describe aquello que carece de agua. Jesús habla de un espíritu inmundo que vaga por ''lugares secos'' buscando descanso (Matt 12:43; Luke 11:24), evocando el desierto como morada de demonios. En 2 Peter 2:17 y Jude 1:12, la palabra se aplica metafóricamente a los falsos maestros: son ''fuentes sin agua'' o ''nubes sin agua'', que prometen refrigerio pero no entregan nada. La construcción privativa griega se preserva de manera transparente en castellano como ''sin agua''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0505', 'spa', 'Sincero, genuino, sin hipocresía; describe el amor, la fe y la sabiduría libres de fingimiento', 'Adjetivo compacto (ἀ-νυπόκριτος, literalmente «no actuado») que significa libre de fingimiento o simulación. Modifica las virtudes cristianas más centrales: el amor debe ser «sin hipocresía» (Ro 12:9), al igual que la fe (1 Ti 1:5; 2 Ti 1:5) y la sabiduría de lo alto (Stg 3:17). La expresión española «sin hipocresía» preserva hermosamente la estructura alfa privativa. El vocablo insiste en que la realidad interior debe coincidir con la profesión exterior, una preocupación recurrente en las cartas apostólicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0506', 'spa', 'insubordinado, rebelde, no sujeto a autoridad; también ''aún no sometido'' en sentido cósmico-escatológico', 'Compuesto de la alfa privativa y ὑποτάσσω (''sujetar, ordenar bajo''), este adjetivo describe lo que no ha sido puesto bajo autoridad. Aparece en dos registros distintos. En las Epístolas Pastorales caracteriza a personas rebeldes: los desobedientes e insubordinados (1 Tim 1:9), hijos indisciplinados (Titus 1:6) y los muchos contumaces y engañadores (Titus 1:10). Sin embargo, Hebrews 2:8 lo emplea en un sentido cósmico-escatológico: citando el Psalm 8, el autor señala que nada quedó ''sin sujetar'' al ser humano, aunque ''todavía no vemos todas las cosas sujetas''. El castellano ''insubordinado'' capta bien el matiz de desafío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0507', 'spa', 'Arriba, hacia arriba; adverbio de posición o dirección espacial, frecuentemente extendido al sentido celestial o espiritualmente superior.', 'Este adverbio transmite la idea espacial básica de «arriba» o «hacia arriba», pero en el Nuevo Testamento a menudo conlleva un peso teológico considerable. Jesús dice a los siervos que llenen las tinajas «hasta arriba» (Jn 2:7), un uso puramente espacial. Sin embargo, en Jn 8:23 declara «yo soy de arriba» (ἐγὼ ἐκ τῶν ἄνω εἰμί), contrastando el ámbito celestial con el terrenal, una distinción que Pablo retoma en Gálatas 4:26: «la Jerusalén de arriba es libre». Colosenses 3:1-2 exhorta a los creyentes a buscar «las cosas de arriba». El español arriba y de arriba preservan bien este doble sentido espacial y espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0508', 'spa', 'aposento alto, cámara superior; el piso elevado de una casa usado para comer o reunirse', 'Este sustantivo designa un aposento alto o cámara superior. Ambas apariciones en los evangelios describen el gran aposento alto donde Jesús comió la Última Cena. Marcos 14:15 y Lucas 22:12 usan la misma frase: un gran aposento alto, amueblado y preparado. El uso clásico incluía pisos superiores usados para almacenamiento o comidas. El Nuevo Testamento lo restringe a este espacio significativo donde Jesús instituyó la Cena del Señor. Las traducciones (español aposento-alto/salón-alto, francés chambre-haute) enfatizan la elevación y el tamaño del cuarto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0509', 'spa', 'De arriba, del cielo; desde el principio, desde antiguo; de nuevo, otra vez.', 'De arriba, del cielo; desde el principio, desde antiguo; de nuevo, otra vez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0511', 'spa', 'más alto, arriba; comparativamente más elevado en posición o mencionado anteriormente en el texto', 'Este adjetivo comparativo significa más alto o arriba, usado tanto espacial como textualmente. Lucas 14:10 describe el moverse hacia un lugar más alto de honor en un banquete. Hebreos 10:8 se refiere a lo que se dijo arriba anteriormente en el texto. La palabra es la forma comparativa de ἄνω (hacia arriba, arriba). El uso clásico incluía obtener ventaja sobre algo y posiciones físicamente más altas. El Nuevo Testamento lo usa tanto para elevación social como para referencia textual. Las traducciones (español arriba/más-arriba, alemán hoeher) funcionan espacialmente, mientras que ''arriba'' funciona para referencia textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0512', 'spa', 'inútil, improductivo, sin provecho; que no proporciona beneficio ni ventaja', 'Este adjetivo describe lo que es inútil o improductivo—que no proporciona beneficio alguno. Tito 3:9 llama a las controversias necias, genealogías y disputas sobre la ley inútiles e improductivas. Hebreos 7:18 describe el antiguo mandamiento como débil e inútil. El uso clásico incluía tanto lo improductivo como lo activamente dañino. El Nuevo Testamento lo limita a lo inservible o carente de beneficio. Las traducciones (español inutilidad/inútiles, francés inutile, alemán unnuetz) enfatizan consistentemente la inutilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0513', 'spa', 'hacha; herramienta con hoja pesada usada para cortar madera o derribar árboles', 'Este sustantivo denota un hacha—una herramienta cortante con hoja pesada. Ambas ocurrencias aparecen en pasajes paralelos de la predicación de Juan el Bautista. Mateo 3:10 y Lucas 3:9 citan la advertencia de Juan de que el hacha ya está puesta a la raíz del árbol, lista para cortar los árboles infructuosos. El uso clásico incluía hachas, hachas de guerra y hachas para cortar leña. El Nuevo Testamento lo limita a la imagen profética de Juan sobre el juicio venidero. Las traducciones (español hacha, francés hache) identifican consistentemente esto como un hacha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0514', 'spa', 'Digno, merecedor, apropiado — describe a alguien o algo que merece honor, castigo o un estatus determinado.', 'Digno, merecedor, apropiado — describe a alguien o algo que merece honor, castigo o un estatus determinado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0515', 'spa', 'Considerar digno, juzgar merecedor; en voz pasiva: ser tenido por digno de honor, vocación o castigo', 'El verbo griego ἀξιόω conlleva el peso de una evaluación deliberada: mirar a alguien y juzgar si está a la altura. En voz activa significa «considerar digno» o «estimar apropiado», como cuando el centurión dice a Jesús «no me tuve por digno de ir a ti» (Lc 7:7) o cuando Pablo no consideró conveniente llevar a Marcos (Hch 15:38). En voz pasiva se convierte en «ser tenido por digno» o «ser juzgado merecedor», y aquí las implicaciones se elevan: los tesalonicenses son tenidos por dignos del llamamiento de Dios (2 Ts 1:11), los ancianos merecen doble honor (1 Ti 5:17), Jesús es considerado digno de mayor gloria que Moisés (He 3:3), y — lo más solemne — los apóstatas son juzgados merecedores de peor castigo (He 10:29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0516', 'spa', 'Dignamente, de manera digna de; adverbio que exhorta a una conducta acorde con la vocación o el evangelio', 'Adverbio derivado de ἄξιος («digno, de igual peso») que llama a los creyentes a vivir de un modo proporcionado a la dignidad de su vocación. Pablo lo emplea repetidamente como bisagra entre la teología y la ética: andar «dignamente» de la vocación recibida (Ef 4:1), del evangelio de Cristo (Fil 1:27), del Señor (Col 1:10) y del Dios que os llama (1 Ts 2:12). El español «dignamente» preserva con exactitud la fuerza adverbial. Romanos 16:2 pide a la iglesia que reciba a Febe «como es digno de los santos».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0517', 'spa', 'Invisible, que no puede percibirse con la vista física; se aplica especialmente a la naturaleza y atributos de Dios.', 'En el Nuevo Testamento este adjetivo se aplica exclusivamente al ámbito divino, describiendo lo que está más allá de la percepción visual humana. Pablo lo emplea con fuerza en Ro 1:20, argumentando que las cualidades invisibles de Dios se «perciben claramente» a través de la creación, una tensión retórica deliberada. En Col 1:15-16 Cristo es la imagen del Dios invisible, y todas las cosas visibles e invisibles fueron creadas por medio de él. El término aparece en la doxología al «Dios inmortal, invisible, único» (1 Ti 1:17) y en el elogio de Moisés que perseveró «como viendo al Invisible» (Heb 11:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0518', 'spa', 'Informar, traer noticias; proclamar o anunciar públicamente; ser informado.', 'Informar, traer noticias; proclamar o anunciar públicamente; ser informado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0520', 'spa', 'Llevar (a una persona bajo custodia); en voz pasiva: ser llevado o arrastrado; en sentido figurado: de un camino que conduce a algún lugar.', 'Llevar (a una persona bajo custodia); en voz pasiva: ser llevado o arrastrado; en sentido figurado: de un camino que conduce a algún lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0522', 'spa', 'Quitar, arrebatar, llevarse; levantar algo y apartarlo con fuerza', 'Este verbo significa levantar algo y llevárselo, resultando en su remoción. Jesús lo emplea en los tres relatos sinópticos de la parábola del esposo: cuando el esposo «sea quitado», entonces los discípulos ayunarán (Mateo 9:15; Marcos 2:20; Lucas 5:35). La voz pasiva subraya que la remoción le sucede al esposo, prefigurando la pasión de Jesús. La imagen evoca un arrebatamiento forzoso, una separación repentina que deja ausencia y duelo tras de sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0523', 'spa', 'exigir de vuelta, reclamar, pedir de regreso; requerir pago o rendir cuentas', 'Este verbo significa exigir de vuelta o requerir la devolución de algo. Ambas ocurrencias aparecen en Lucas. En Lucas 6:30, Jesús enseña a no reclamar lo que nos quitan. Lucas 12:20 registra la declaración de Dios al rico insensato: ''Esta noche te reclaman tu alma.'' El uso clásico incluía exigir cosas tomadas por la fuerza, invocar castigo y requerir pago. El Nuevo Testamento lo usa para exigir devolución y rendición de cuentas divina. Las traducciones (español demandan/reclames, francés redemander) enfatizan el aspecto de exigir o requerir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0525', 'spa', 'Liberar, soltar, partir; ser librado de algo o marcharse', 'Este verbo en voz media o pasiva significa ser liberado de algo o partir. Jesús advierte al injusto que se ponga de acuerdo con su adversario antes del juicio, para que no deje de «ser soltado» hasta pagar por completo (Lucas 12:58). Hechos 19:12 relata cómo las enfermedades «se apartaban» de las personas mediante los pañuelos de Pablo. Hebreos 2:15 describe a Cristo liberando a quienes por temor a la muerte vivían sujetos a esclavitud perpetua: vino a «librarlos» de esa servidumbre. La palabra tiende un puente entre la partida física y la liberación espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0526', 'spa', 'Enajenado, apartado; separado o excluido de una relacion o comunidad por distanciamiento activo', 'Este participio perfecto pasivo describe a quienes han sido enajenados o separados de algo vital. Pablo lo emplea tres veces para retratar la separacion de los gentiles respecto a la comunidad del pacto de Dios. En Efesios 2:12 recuerda cuando estaban «ajenos a la ciudadania de Israel». Efesios 4:18 describe a los incredulos como «enajenados de la vida de Dios» a causa de su ignorancia. Colosenses 1:21 recuerda a los creyentes que antes eran «extraños y enemigos» en su mente. La palabra transmite no una mera distancia, sino un distanciamiento activo de la relacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0527', 'spa', 'tierno, suave; físicamente suave al tacto, delicado, joven y flexible', 'Este adjetivo describe lo que es tierno o suave al tacto. Ambas ocurrencias evangélicas aparecen en enseñanza parabólica paralela. Mateo 24:32 y Marcos 13:28 describen la rama de la higuera volviéndose tierna como señal de que el verano está cerca. El uso clásico describía cuerpos humanos delicados, animales jóvenes, huevos pasados por agua y carácter gentil. El Nuevo Testamento lo limita a esta ternura botánica que indica cambio estacional. El español tierna y el francés tendre enfatizan la calidad tierna y flexible del nuevo crecimiento primaveral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0528', 'spa', 'encontrar, encontrarse con, salir al encuentro; moverse hacia alguien y encontrarlo', 'Este verbo significa encontrar o encontrarse con alguien, a menudo implicando movimiento hacia la persona. Marcos 14:13 describe a un hombre llevando un cántaro de agua que se encontrará con los discípulos. Lucas 17:12 cuenta de diez leprosos que se encontraron con Jesús al entrar Él a una aldea. El uso clásico incluía encontrar personas, enfrentar situaciones y toparse con gente. El Nuevo Testamento lo usa para encuentros con personas en un viaje. Las traducciones (español salir-al-encuentro, francés rencontrer) enfatizan el aspecto de encontrar o toparse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0529', 'spa', 'Encuentro, recibimiento; salida al encuentro de alguien que se aproxima', 'Este sustantivo designa un encuentro o recibimiento, especialmente aquel en que se sale al paso de alguien que se acerca. En la parabola de las diez virgenes, salen al «encuentro» del esposo (Mt 25:6). Hechos 28:15 relata como los creyentes de Roma fueron a «recibir» a Pablo hasta el Foro de Apio y Tres Tabernas. De modo culminante, 1 Tesalonicenses 4:17 habla de los creyentes arrebatados en las nubes para «recibir» al Senor en el aire. La palabra subraya la accion deliberada de salir al encuentro de una persona de importancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0530', 'spa', 'Una vez: una sola vez; de una vez por todas, de manera decisiva e irrepetible.', 'Una vez: una sola vez; de una vez por todas, de manera decisiva e irrepetible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0533', 'spa', 'Negar, renegar, renunciar — repudiar la asociación con alguien, especialmente con Cristo; también negarse a sí mismo. El verbo ἀπαρνέομαι (aparneomai)', 'Negar, renegar, renunciar — repudiar la asociación con alguien, especialmente con Cristo; también negarse a sí mismo. El verbo ἀπαρνέομαι (aparneomai) intensifica la negación simple de ἀρνέομαι mediante el prefijo ἀπο-, convirtiéndola en un rechazo total. Está vinculado para siempre con la triple negación de Pedro (Mt 26:34-35, 75; Mr 14:30-31, 72; Lc 22:34, 61), predicha por Jesús en la Última Cena. Sin embargo, el mismo verbo aparece en el llamado al discipulado: ''Niéguese a sí mismo y tome su cruz'' (Mt 16:24; Mr 8:34; Lc 9:23). La palabra abarca así desde el abandono infiel hasta la entrega radical de uno mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0534', 'spa', 'exactamente, justo, por completo (con números); desde ahora, en adelante (temporal)', 'Adverbio con dos aplicaciones temporales distintas. En el uso clásico significaba «exactamente» o «justo» al referirse a cantidades: noventa días exactos. También podía significar «justo lo contrario» en afirmaciones contrastantes. En el Nuevo Testamento (escrito propiamente como dos palabras, ἀπ'' ἄρτι) adquiere un sentido temporal: «desde ahora» o «en adelante», marcando un punto de transición a partir del cual algo comienza o cambia. Este sentido temporal también puede significar «ahora mismo» o «incluso ahora», refiriéndose al momento presente inmediato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0536', 'spa', 'Primicias: la porción inicial de una cosecha o grupo, consagrada a Dios y representativa del todo que le sigue.', 'Enraizado en la práctica israelita de ofrecer a Dios la primera porción de la cosecha como señal de que toda la siega le pertenece, este término se convierte en una metáfora poderosa en la teología paulina. Cristo es «las primicias de los que durmieron» (1 Co 15:20, 23): su resurrección garantiza la cosecha de todos los creyentes. El Espíritu es «las primicias» de la redención venidera (Ro 8:23). Los primeros convertidos de un hogar o región son llamados «primicias» (Ro 16:5; 1 Co 16:15). Y si la masa ofrecida como primicias es santa, también lo es toda la masa (Ro 11:16). El español primicias preserva fielmente la metáfora agrícola y sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0537', 'spa', 'Forma intensificada de πᾶς (''todo''), construida con el prefijo colectivo ἁ- (afín al sánscrito sam-, ''juntos''), que subraya la totalidad con fuerza re', 'Forma intensificada de πᾶς (''todo''), construida con el prefijo colectivo ἁ- (afín al sánscrito sam-, ''juntos''), que subraya la totalidad con fuerza retórica. Donde πᾶς podría dejar margen a la generalización, ἅπας insiste en que nadie queda excluido. Sus 32 apariciones neotestamentarias surgen en momentos de universalidad enfática: la multitud quedó ''del todo'' asombrada (Marcos 1:27), ''todas las cosas'' fueron referidas a los principales sacerdotes (Mateo 28:11), y ''cada uno'' de la generación del diluvio pereció (Lucas 17:27). Lucas-Hechos concentra la mayoría de los usos, reflejando la predilección de Lucas por cuantificadores enfáticos. En todos los idiomas la traducción se reduce al mismo vocablo usado para πᾶς — español ''todo/todos,'' francés ''tous,'' alemán ''alle'' — porque la mayoría de las lenguas carecen de un cuantificador universal enfático independiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0538', 'spa', 'Enganar, seducir, defraudar; inducir al error mediante el engano', 'Este verbo significa enganar o seducir a alguien, conduciendolo al error. Pablo advierte a los creyentes que nadie los «engane» con palabras vanas acerca del juicio de Dios (Ef 5:6). En 1 Timoteo 2:14, senala que Adan no fue enganado, pero la mujer, «siendo enganada», cayo en transgresion. Santiago advierte que quien se cree religioso pero no refrena su lengua «engana» su propio corazon (1:26). La palabra aparece tanto en forma activa como pasiva, mostrando el engano como algo que se ejerce sobre otros o que uno mismo padece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0539', 'spa', 'Engaño, decepción, astucia; el acto o cualidad de inducir al error mediante falsedad o artimañas', 'Sustantivo abstracto que designa el engaño, el fraude o la decepción: el acto deliberado o la cualidad insidiosa de inducir al error. En la Parábola del Sembrador, es «el engaño de las riquezas» lo que ahoga la palabra (Mt 13:22; Mr 4:19), personificando el poder seductor de la riqueza para engañar. Pablo advierte contra ser capturados por «el vano engaño» (Col 2:8) e identifica al escatológico «hombre de iniquidad» con «todo engaño de injusticia» (2 Ts 2:10). El uso neotestamentario no admite subdivisión: engaño es engaño en todas sus apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0542', 'spa', 'mirar con atención, fijar la vista en algo; apartar la mirada con desprecio', 'Verbo aoristo (sin forma presente de uso común) que posee dos sentidos contrastantes. El significado principal consiste en apartar la mirada de otras cosas para concentrar la atención en algo específico, dirigiendo los ojos hacia un objeto o persona con enfoque deliberado. El segundo sentido, quizá derivado de esa idea de desviar la mirada, adquiere el significado metafórico de despreciar o mirar con desdén. El elemento direccional («apartándose de lo demás») subyace tanto en la atención concentrada del primer sentido como en la actitud despectiva del segundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0543', 'spa', 'Desobediencia, negativa a obedecer; resistencia voluntaria a la autoridad, especialmente al mandato divino.', 'Designa la desobediencia o el incumplimiento deliberado, particularmente hacia la voluntad revelada de Dios. Pablo lo emplea como término teológico clave en Romanos 11 para describir la desobediencia corporativa de Israel, que paradójicamente abre la puerta de la misericordia a los gentiles (Ro 11:30, 32). En Ef 2:2 caracteriza el estado previo a la conversión como andar en «el espíritu de desobediencia», mientras que Ef 5:6 y Col 3:6 advierten que la ira de Dios viene sobre «los hijos de desobediencia». El español «desobediencia», el francés «désobéissance» y el alemán «Ungehorsam» conservan la misma estructura privativa: des-obediencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0544', 'spa', 'Desobedecer, ser desobediente: negarse a cumplir con la autoridad o rechazar la persuasion de la verdad.', 'Desobedecer, ser desobediente: negarse a cumplir con la autoridad o rechazar la persuasion de la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0545', 'spa', 'Desobediente, rebelde; que rehúsa obedecer la autoridad divina o legítima.', 'Adjetivo que describe la negativa voluntaria a obedecer, especialmente hacia Dios. Aparece en contextos que van de lo esperanzador a lo severo: en Lucas 1:17 el ángel promete que el espíritu de Elías convertirá «a los desobedientes» a la prudencia de los justos. Pablo relata su obediencia a la visión celestial declarando que «no fui desobediente» (Hch 26:19). Los catálogos de vicios de Romanos 1:30, 2 Timoteo 3:2 y Tito 1:16 lo incluyen entre las marcas de una vida depravada. El español «desobediente» y el francés «désobéissant» reflejan directamente la estructura alfa-privativa del griego (ἀ-πειθής, «in-persuasible»).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0546', 'spa', 'amenazar, proferir amenazas; hablar de manera amenazante o advertir con intimidación', 'Este verbo describe un discurso destinado a intimidar o coaccionar mediante advertencias de daño. En Hechos 4:17, el Sanedrín debate ''amenacémoslos'' para silenciar el testimonio de los apóstoles acerca de Jesús. En 1 Pedro 2:23, se alaba a Cristo porque ''cuando padecía, no amenazaba''. La palabra conlleva la fuerza de usar lenguaje intimidante para controlar el comportamiento. El uso griego clásico incluía tanto prometer como amenazar (Homero), pero el uso bíblico se restringe al sentido amenazante. Las traducciones multilingües (español ''amenazar'', francés ''menacer'') reconocen consistentemente el carácter intimidante de este acto de habla, aunque el alemán simplemente proporciona formas griegas, sugiriendo reconocimiento de su estatus técnico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0547', 'spa', 'Amenaza, intimidacion; palabras o acciones amenazantes dirigidas a amedrentar', 'Este sustantivo designa amenazas o declaraciones intimidatorias. Hechos registra como la iglesia primitiva oraba frente a las «amenazas» de sus opositores (4:29). Se describe a Saulo «respirando amenazas y muerte» contra los discipulos antes de su conversion (9:1). Pablo instruye a los amos a abandonar las «amenazas» hacia los esclavos, sabiendo que comparten un mismo Senor en los cielos (Ef 6:9). La forma plural aparece con frecuencia, sugiriendo palabras amenazantes repetidas o multiples. El contexto siempre involucra la intencion hostil de intimidar o causar dano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0548', 'spa', 'Estar ausente, estar lejos; el estado de separación física de una persona o lugar.', 'Verbo que significa «estar lejos» o «estar ausente», formado de ἀπό (lejos de) y εἰμί (ser/estar). En el Nuevo Testamento aparece casi exclusivamente en las cartas de Pablo, donde contrasta la ausencia física con la presencia espiritual o de autoridad. Escribiendo a Corinto, insiste en que, aunque «ausente en cuerpo», está presente en espíritu para juzgar al hombre inmoral (1 Co 5:3), y advierte que lo que dice por carta estando ausente lo llevará a cabo cuando esté presente (2 Co 10:11; 13:2, 10). El vocablo refleja la tensión pastoral del liderazgo apostólico ejercido a distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0553', 'spa', 'Aguardar con anhelo e intensa expectativa, especialmente respecto a la salvación futura o el cumplimiento divino.', 'Verbo compuesto formado por ἀπό + ἐκ + δέχομαι, que intensifica la idea básica de recibir hasta convertirla en un esfuerzo anhelante de profunda esperanza. En el Nuevo Testamento aparece exclusivamente en contextos de esperanza escatológica: los creyentes que aguardan la redención del cuerpo (Rom 8:23), la revelación de Cristo (1 Cor 1:7) y la esperanza de justicia por la fe (Gal 5:5). El español ''aguardar'' capta bien esta nota de expectativa paciente pero ferviente. Pablo emplea este vocablo para describir a toda la creación gimiendo en anticipación (Rom 8:19), dándole un alcance cósmico que trasciende la simple espera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0554', 'spa', 'despojar, despojarse; (voz media) desarmar, desvestir; metafóricamente, quitarse como una vestidura', 'Este verbo compuesto combina ἀπό (''de, desde'') y ἐκδύω (''desnudar, desvestir'') en su forma intensiva de voz media, representando la remoción decisiva de algo usado o adherido. En Colosenses, Pablo lo usa dos veces con fuerza metafórica impactante. En 2:15, Cristo ''despojó a los gobernantes y autoridades'', quitándoles su poder como quien remueve armas o armadura. En 3:9, los creyentes se han ''despojado del viejo yo'' como quien se quita ropas sucias. La voz media enfatiza la participación personal del sujeto: el despojo activo de Cristo sobre los poderes hostiles; la separación decisiva del creyente de su identidad anterior. La imagen física de desvestirse transmite poderosamente una remoción y transformación completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0561', 'spa', 'Enfrente, delante de, en presencia de; también puede significar «contra» o «contrario a».', 'Esta preposición expresa oposición espacial —estar cara a cara o directamente frente a algo— y se extiende a sentidos figurados de confrontación o presencia. En Mt 27:61 María Magdalena y la otra María se sientan «enfrente» del sepulcro, una imagen espacial vívida. Mt 27:24 muestra a Pilato lavándose las manos «delante» de la multitud. Hch 3:16 y Ro 3:18 la emplean con el sentido de «en presencia de», mientras que Hch 17:7 se inclina hacia el matiz adversativo de actuar «contra» los decretos del César.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0565', 'spa', 'Irse, partir; de cosas o condiciones: pasar, cesar; también de noticias que se difunden o de ir en pos de algo', 'Ἀπέρχομαι es el verbo de uso corriente en el Nuevo Testamento para la partida: simple, físico y frecuente. Compuesto de ἀπό («lejos de») y ἔρχομαι («venir/ir»), describe el movimiento humano más básico de dejar un lugar y dirigirse a otro. Las parábolas de Jesús están llenas de él: la audiencia del sembrador «se va» (Mt 13:25), el mercader «va» a venderlo todo por la perla (Mt 13:46), y los invitados «se marchan» a sus campos y negocios (Mt 22:5). En los Evangelios funciona frecuentemente como marcador de transición narrativa. Un sentido secundario, más silencioso pero teológicamente profundo, emerge en Apocalipsis, donde el verbo pasa de lo espacial a lo temporal: «el primer ay ha pasado» (Ap 9:12), «el primer cielo y la primera tierra pasaron» (Ap 21:1). Dos usos raros completan el cuadro: noticias que «salen» por una región (Mt 4:24) y la descripción en Judas de Sodoma «yendo en pos de» vicios (Jud 7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0566', 'spa', 'mantener alejado, apartar; estar distante; recibir en su totalidad; bastar (voz media)', 'Verbo compuesto versátil con varios sentidos relacionados, articulados en torno a la idea central de separación o distancia. En voz activa incluye mantener algo apartado o alejado de otra cosa: la clavícula separa el cuello de los hombros. Puede significar contener las manos para no tocar a alguien, o en construcción impersonal, indicar que nada impide una acción. La voz media desarrolla significados comerciales y experienciales propios: haber recibido algo íntegramente (especialmente un pago), estar distante de un lugar o abstenerse de algo. Entre sus matices adicionales se encuentran el ser suficiente y, en textos más antiguos, regresar de un viaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0567', 'spa', 'apartar, mantener a distancia; recibir en su totalidad; abstenerse (voz media); bastar', 'Verbo compuesto versátil cuyo sentido central gira en torno a la idea de separación o distancia. En voz activa significa apartar algo o mantenerlo alejado, retener las manos o, en construcción impersonal, indicar que nada impide una acción. En voz media desarrolla significados comerciales y vivenciales distintivos: haber recibido algo en su totalidad (especialmente un pago), estar lejos de un lugar o abstenerse de algo. También puede expresar suficiencia y, en textos más antiguos, regresar de un viaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0568', 'spa', 'Recibir en su totalidad, abstenerse, estar distante o (impersonalmente) bastar — un verbo versátil de separación, cumplimiento y distancia.', 'Recibir en su totalidad, abstenerse, estar distante o (impersonalmente) bastar — un verbo versátil de separación, cumplimiento y distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0569', 'spa', 'No creer, rehusar creer o ser infiel; la contraparte verbal de ἄπιστος (incrédulo).', 'Derivado del prefijo privativo alfa (ἀ-) y πιστεύω (creer), este verbo describe el rechazo activo o la incapacidad de creer. Aparece en momentos narrativos decisivos: los discípulos que no creen el informe de la resurrección (Mar 16:11; Luc 24:11, 41), la respuesta dividida ante la predicación de Pablo en Roma (Hch 28:24) y la solemne advertencia de que quien no creyere será condenado (Mar 16:16). En 2 Timoteo 2:13 adquiere un giro teológico notable: aunque seamos infieles, Dios permanece fiel. El término abarca tanto la incredulidad puntual ante un mensaje como la infidelidad persistente de carácter.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0570', 'spa', 'Incredulidad, falta de fe — rechazo o incapacidad de confiar en Dios, que obstaculiza la acción divina y la relación de pacto. El sustantivo ἀπιστία (', 'Incredulidad, falta de fe — rechazo o incapacidad de confiar en Dios, que obstaculiza la acción divina y la relación de pacto. El sustantivo ἀπιστία (apistia) designa la ausencia o el rechazo de la fe, no como mera duda intelectual, sino como una disposición que obstruye la obra de Dios. Jesús ''no hizo muchos milagros'' en Nazaret ''a causa de la incredulidad de ellos'' (Mt 13:58; cf. Mr 6:6), y el padre del muchacho epiléptico clama: ''¡Creo; ayuda mi incredulidad!'' (Mr 9:24). El uso teológico de Pablo en Romanos es especialmente rico: la incredulidad de Israel abrió la puerta a la inclusión de los gentiles (Ro 11:20, 23), pero ni siquiera la infidelidad de Israel puede anular la fidelidad de Dios (Ro 3:3). El autor de Hebreos advierte contra ''un corazón malo e incrédulo'' que se aparta del Dios vivo (He 3:12, 19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0571', 'spa', 'Incrédulo, sin fe; como sustantivo: un incrédulo; también increíble, difícil de creer', 'Incrédulo, sin fe; como sustantivo: un incrédulo; también increíble, difícil de creer');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0572', 'spa', 'Sencillez de corazón que se manifiesta como generosidad liberal o sinceridad de devoción sin doblez.', 'Sustantivo arraigado en la idea de ''unicidad'': un corazón indiviso, sin pliegues ni capas ocultas. En el Nuevo Testamento se ramifica en dos sentidos estrechamente relacionados pero distinguibles: la generosidad al dar y la sinceridad en la devoción. La profunda pobreza de los macedonios desbordó en ''riqueza de generosidad'' (2 Cor 8:2), mientras que a los siervos se les manda obedecer con ''sencillez de corazón'' (Ef 6:5; Col 3:22). Ambos sentidos brotan de la misma fuente: un corazón ἁπλοῦς (simple, íntegro) que da sin cálculo o se entrega sin duplicidad. El alemán ''Einfalt'' (literalmente ''un solo pliegue'') conserva bellamente esta unidad etimológica en ambos usos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0573', 'spa', 'simple, sencillo, claro; metafóricamente de simplicidad moral, sinceridad de propósito, generosidad sin doblez', 'La palabra lleva el significado básico de ''simple'' en oposición a ''doble'' o ''dividido'', pero en su uso neotestamentario describe el carácter moral. Jesús la usa para describir un ojo que es ''claro'' o ''sano'', uno que ve correctamente y deja entrar la luz, en contraste con un ojo malo que está nublado o enfermo. La evidencia multilingüe revela un matiz interesante: el español ''sencillo'' (simple, sincero) y el inglés ''clear, healthy'' (claro, sano) apuntan a la dimensión moral, sugiriendo generosidad sin pretensiones y devoción incondicional a Dios. La metáfora del ojo en Mateo 6 y Lucas 11 conecta la vista física con la percepción espiritual, donde la simplicidad de visión significa lealtad indivisa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0575', 'spa', 'De, desde, a partir de; marca origen, separación, causa o agencia', 'Preposición versátil que rige genitivo y expresa primariamente separación o punto de partida. Indica el origen espacial, temporal o lógico de una acción o estado. En contextos causales señala la fuente o razón (''a causa de''), mientras que en construcciones pasivas puede introducir el agente indirecto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0576', 'spa', 'descender, desembarcar; resultar, tener un desenlace determinado', 'Este verbo compuesto (ἀπό + βαίνω, ''apartarse de un lugar'') posee tanto un sentido físico como uno resultativo. Físicamente, significa descender o desembarcar: en Luke 5:2 los pescadores habían bajado de sus barcas, y en John 21:9 los discípulos desembarcan tras la aparición del Resucitado. Pero Luke 21:13 lo emplea en un registro completamente diferente: Jesús dice a sus seguidores perseguidos que sus pruebas ''resultarán'' en ocasión para dar testimonio. Philippians 1:19 lo reitera: Pablo confía en que su encarcelamiento ''resultará'' en su liberación. El castellano distingue bien ambos sentidos: ''desembarcar'' para lo físico y ''resultar'' para el desenlace.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0577', 'spa', 'desechar, arrojar; rechazar o descartar algo previamente poseído o usado', 'Este verbo representa la acción enérgica de arrojar algo lejos de uno mismo, ya sea quitarse una vestidura, echar carga de un barco, o rechazar algo antes valorado. El rango del griego clásico incluye contextos militares (arrojar la armadura) y comerciales (vender demasiado barato, cortar pérdidas). En las dos ocurrencias neotestamentarias, lo físico y lo metafórico se fusionan: Bartimeo arroja su manto en su afán por llegar a Jesús, mientras que Hebreos advierte a los creyentes que no desechen su confianza. El español ''desechéis'' (rechazar, descartar) y ''habiendo arrojado'' capturan tanto el vigor físico como lo decisivo de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0580', 'spa', 'el acto de desechar, pérdida, rechazo; el acto de descartar o el estado de haber perdido algo', 'Este sustantivo nombra el resultado de arrojar algo, ya sea el desecho voluntario de carga para salvar un barco o la pérdida involuntaria de algo valorado. El griego clásico lo usaba para el abandono de armas en retirada o la omisión de letras en gramática. Pablo lo emplea teológicamente en Romanos 11 para el ''rechazo'' de Israel por Dios (un rechazo que paradójicamente trae reconciliación al mundo), mientras que Lucas lo usa en Hechos 27 para la ''pérdida'' literal de vida evitada en el naufragio. La evidencia multilingüe se divide entre ''pérdida'' (un estado) y ''rechazo'' (un acto), ambos matices válidos del término griego único.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0582', 'spa', 'un registro, censo, empadronamiento; lista oficial de personas o propiedades con fines tributarios o cívicos', 'Este término técnico-administrativo denotaba el censo romano: un registro periódico de personas y propiedades para la organización tributaria y cívica. El griego clásico lo usaba ampliamente para registros, listas y declaraciones, pero en tiempos del Nuevo Testamento se refería específicamente a los empadronamientos imperiales ordenados por decreto. Lucas lo menciona dos veces, ambas veces anclando eventos evangélicos en historia datable: el censo bajo Quirinio que llevó a María y José a Belén, y el censo bajo Quirinio que provocó la revuelta de Judas el Galileo. Las glosas multilingües convergen en ''censo'' y ''registro'', reflejando la precisión burocrática del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0583', 'spa', 'inscribir, empadronar; registrarse en un censo o lista oficial', 'Usado en el Nuevo Testamento principalmente para el censo romano que llevó a José y María a Belén (Luke 2:1-5), este verbo denota la inscripción o el empadronamiento oficial, generalmente con fines tributarios. En la voz media predominante en el NT, enfatiza el cumplimiento voluntario del decreto imperial. En Hebrews 12:23 adquiere un registro celestial: los nombres de los primogénitos inscritos en el cielo. El castellano ''empadronarse'' capta con precisión el matiz censal, mientras que ''inscribir'' abarca la idea más amplia de ser anotado en un registro oficial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0584', 'spa', 'exhibir, demostrar, mostrar públicamente; presentar pruebas o manifestar algo de manera evidente', 'En su núcleo, este verbo significa señalar o demostrar públicamente algo, ya sea mediante señales milagrosas o mediante argumentación. En Acts 2:22, Dios ''acreditó'' a Jesús mediante prodigios y señales, una legitimación divina. Pablo en 1 Corinthians 4:9 afirma que Dios ha exhibido a los apóstoles como un espectáculo. El castellano ''exhibió'' y ''mostrándose'' captan el rango desde la exhibición teatral hasta la demostración racional. En 2 Thessalonians 2:4, el hombre de iniquidad ''se exhibe'' a sí mismo como Dios, una autoexhibición blasfema.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0586', 'spa', 'Diezmar; dar o recaudar la décima parte como obligación religiosa', 'Enraizado en la antigua práctica de entregar la décima parte a Dios, este verbo opera en dos direcciones: pagar diezmos y recaudarlos. Jesús reprende a los fariseos por diezmar meticulosamente hierbas como la menta y el eneldo mientras descuidan la justicia (Matt 23:23; Luke 11:42). La jactancia del recaudador de impuestos «yo diezmo todo lo que adquiero» (Luke 18:12) ilustra una precisión farisaica. En Hebrews 7:5, los sacerdotes levíticos recaudan los diezmos del pueblo. El término griego, al igual que el español «diezmar/diezmo», conserva la etimología explícita de la décima parte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0587', 'spa', 'aceptable, grato, agradable (especialmente a Dios o en contextos religiosos)', 'Este adjetivo describe lo que es aceptable, grato o agradable, particularmente en contextos de aprobación divina. Pablo lo usa dos veces en 1 Timoteo para describir cosas que son ''aceptables a Dios'': la oración intercesora por todas las personas (2:3) y proveer para la propia familia (5:4). La traducción consistente como ''aceptable'' o ''agradable'' en varios idiomas (español aceptable, alemán angenehm) refleja su sentido central de cumplir un estándar o hallar favor, con matices teológicos de lo que Dios acoge con beneplácito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0588', 'spa', 'Recibir con agrado, acoger; aceptar a una persona con hospitalidad o un mensaje con aprobación.', 'ἀποδέχομαι combina el prefijo ἀπό («desde») con δέχομαι («recibir»), formando un verbo que sugiere recibir algo o a alguien de manera plena y favorable. En cinco de sus siete apariciones neotestamentarias describe la acogida de una persona: la multitud que da la bienvenida a Jesús al volver de los gadarenos (Lc 8:40), Jesús recibiendo a las multitudes (Lc 9:11), los hermanos en Acaya acogiendo a Apolos (Hch 18:27), los creyentes de Jerusalén recibiendo al grupo de Pablo (Hch 21:17) y Pablo mismo recibiendo visitantes en Roma (Hch 28:30). Los dos usos restantes pasan a la recepción intelectual: los tres mil en Pentecostés que «recibieron su palabra» (Hch 2:41) y el abogado Tértulo que dice a Félix «lo reconocemos con gratitud» (Hch 24:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0589', 'spa', 'Partir de viaje, viajar a un país lejano; usado casi exclusivamente en parábolas de amos ausentes.', 'Verbo que significa abandonar la propia tierra y viajar al extranjero, formado de ἀπό («lejos») y δῆμος («pueblo, distrito»). En el Nuevo Testamento aparece casi enteramente en las parábolas de Jesús sobre dueños y señores que parten a lugares distantes, confiando sus bienes a los siervos. El dueño de la viña «se fue de viaje» (Mr 12:1; Mt 21:33), el señor reparte talentos antes de partir (Mt 25:14-15), y el hijo pródigo se marcha a una «tierra lejana» (Lc 15:13). El español «partió de viaje» y el francés «voyager» captan el sentido de una ausencia deliberada y prolongada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0591', 'spa', 'Devolver, pagar, retribuir lo debido, vender o producir; abarca restitución, pago de deudas, recompensa, venta y fruto.', 'Formado de ἀπό («de vuelta») y δίδωμι («dar»), ἀποδίδωμι porta el sentido fundamental de entregar algo de vuelta a donde pertenece. La célebre sentencia de Jesús «Dad al César lo que es del César» (Mt 22:21) capta perfectamente la lógica central del verbo: lo que se da ya se debía. El verbo abarca un rango notable: desde saldar deudas financieras en la parábola del siervo malvado (Mt 18:25-34), pasando por la recompensa escatológica de Dios (Mt 16:27), hasta la venta comercial de una primogenitura (He 12:16) y un árbol que «produce» su fruto mes tras mes (Ap 22:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0593', 'spa', 'Rechazar tras examinar o probar; considerar no apto, repudiar o descalificar después de un escrutinio.', 'Verbo compuesto formado por ἀπό (''lejos'') y δοκιμάζω (''probar, aprobar''), que conlleva la fuerza de un rechazo tras evaluación deliberada, no un descarte casual sino un veredicto meditado de ineptitud. Su contexto más prominente en el NT es la cita reiterada del Salmo 118:22: ''la piedra que desecharon los edificadores ha venido a ser cabeza del ángulo'' (Mat 21:42; Mar 12:10; Luc 20:17; 1 Ped 2:4, 7). Jesús también lo emplea respecto a su propio sufrimiento, prediciendo que debe ser ''rechazado por los ancianos'' (Mar 8:31; Luc 9:22; 17:25). El español ''desechar'' y ''rechazar'' subrayan la acción deliberada de apartar, mientras que el prefijo griego ἀπό resalta la finalidad del veredicto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0594', 'spa', 'aceptación, aprobación, recepción favorable (como digno de favor)', 'Este sustantivo denota aceptación o aprobación, especialmente la recepción favorable de algo como digno. Pablo lo usa en dos epístolas pastorales para enfatizar la total confiabilidad de enseñanzas cristianas fundamentales: ''fiel es la palabra y digna de toda aceptación'' respecto a Cristo salvando pecadores (1 Tim 1:15) y la promesa de la piedad (1 Tim 4:9). El rango clásico incluía recibir de vuelta lo que era propio, hospedar invitados y ganar favor o aprobación, pero el Nuevo Testamento estrecha el sentido a aceptar declaraciones de verdad como merecedoras de respaldo total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0595', 'spa', 'acción de quitarse, despojarse, remoción (especialmente de ropa o algo que se lleva puesto)', 'Este sustantivo se refiere al acto de quitarse o dejar a un lado algo—más concretamente ropa, pero extendido metafóricamente a otros tipos de remoción o renuncia. Pedro lo usa dos veces en contextos que mezclan imaginería física y espiritual. En 1 Pedro 3:21, el bautismo ''no es la remoción de suciedad del cuerpo'' sino una apelación a Dios. En 2 Pedro 1:14, el apóstol habla del inminente ''despojamiento de mi tienda'' (su cuerpo/muerte) según Cristo le reveló. El uso clásico incluía almacenar cosas, exposición de niños, incluso renuncia de cargo, pero el Nuevo Testamento se enfoca en la metáfora de remover o dejar a un lado lo que previamente se llevaba puesto o habitaba.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0596', 'spa', 'Granero o depósito para almacenar grano cosechado; usado figuradamente del acopio escatológico o la provisión divina.', 'En el mundo mediterráneo antiguo, la ἀποθήκη era el destino esencial de cada cosecha: el granero o depósito donde se resguardaba el grano. Jesús emplea esta imagen cotidiana de maneras sorprendentes: para tranquilizar a sus discípulos ansiosos recordándoles que Dios alimenta a las aves sin necesidad de graneros (Mt 6:26; Lc 12:24), para ilustrar la separación final del trigo y la paja (Mt 3:12; Lc 3:17), y para dramatizar la necedad del hombre rico que amplía sus graneros mientras descuida su alma (Lc 12:18). Así, el término conecta el mundo agrícola cotidiano con la teología de la provisión y el juicio divinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0599', 'spa', 'Morir; de muerte física (natural, violenta, judicial) o muerte figurada/espiritual (morir al pecado, a la ley, a uno mismo)', 'Forma intensificada de la raíz ''morir'' (θνῄσκω), ἀποθνῄσκω es el verbo estándar del Nuevo Testamento para la muerte en todas sus dimensiones. La mayoría de sus 112 apariciones describen muerte física ordinaria: personas, animales, incluso un grano de trigo que cae en tierra. Pero Pablo transforma el vocablo en herramienta teológica: los creyentes ''mueren al pecado'' en el bautismo (Ro 6:2), ''mueren a la ley'' para vivir para Dios (Gá 2:19) y ''mueren con Cristo'' para participar de la resurrección. La evidencia multilingüe es reveladora: el español morimos y el alemán sterben permanecen idénticos en usos literales y figurados, reflejando cómo Pablo explota deliberadamente el impacto de aplicar lenguaje de muerte a la transformación espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0600', 'spa', 'Restaurar a una condición anterior; restablecer, sanar o devolver algo a su estado original.', 'Verbo de triple composición (ἀπό + κατά + ἵστημι) que significa volver a poner algo donde estaba antes. En los Evangelios aparece con mayor viveza en los relatos de sanidad: la mano seca restaurada a su plenitud (Mat 12:13; Mar 3:5; Luc 6:10) y la vista del ciego restaurada en Betsaida (Mar 8:25). Pero también posee una dimensión escatológica: los discípulos preguntan si Jesús ''restaurará'' el reino a Israel (Hch 1:6), y Jesús enseña que Elías viene primero para ''restaurar todas las cosas'' (Mat 17:11; Mar 9:12). El español ''restaurar'' y el francés ''rétablir'' conservan bien el sentido de devolver a un estado original e intencionado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0601', 'spa', 'Revelar, descubrir o dar a conocer lo que estaba oculto, especialmente cuando Dios manifiesta verdades divinas, su gloria o realidades escatológicas', 'Revelar, descubrir o dar a conocer lo que estaba oculto, especialmente cuando Dios manifiesta verdades divinas, su gloria o realidades escatológicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0602', 'spa', 'Revelación, manifestación — el descubrimiento divino de verdades ocultas o realidades escatológicas.', 'Revelación, manifestación — el descubrimiento divino de verdades ocultas o realidades escatológicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0603', 'spa', 'expectativa ansiosa, anhelo intenso, anticipación anhelante (estirándose hacia adelante para ver)', 'Este sustantivo compuesto vívido (literalmente ''observar desde la cabeza'' o ''estirar el cuello'') captura expectativa intensa y ansiosa—la postura de alguien que se esfuerza hacia adelante, cabeza extendida, para vislumbrar lo que viene. Pablo acuña o adopta este término raro para expresar el anhelo de la creación por la redención (Rom 8:19) y su propia esperanza expectante de que Cristo sea magnificado sea por vida o muerte (Fil 1:20). La etimología evoca anticipación física hecha visible: cabeza proyectada hacia adelante, observando intensamente. Las traducciones consistentemente enfatizan intensidad: español anhelante-expectación, alemán sehnliches-Warten ''espera anhelante'', francés attente-ardente ''espera ardiente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0604', 'spa', 'Reconciliar, restaurar la armonia; restablecer una relacion pacifica tras el distanciamiento', 'Este verbo compuesto intensifica la idea de reconciliacion, llevando a enemigos o distanciados a una relacion armoniosa. Pablo lo emplea exclusivamente para describir la obra reconciliadora cosmica de Cristo. Efesios 2:16 habla de reconciliar a judios y gentiles con Dios en un solo cuerpo mediante la cruz. Colosenses 1:20 proclama el proposito divino de «reconciliar consigo todas las cosas» por la sangre de Cristo. Colosenses 1:22 lo aplica personalmente: «ahora os ha reconciliado» en el cuerpo fisico de Cristo mediante su muerte. El prefijo ἀπο- posiblemente intensifica la idea de restauracion completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0606', 'spa', 'Estar reservado, guardado, almacenado; estar destinado o señalado para algo futuro', 'Funcionando como la voz pasiva de «apartar», este verbo describe algo guardado para uso futuro o asignado por designio divino. Su alcance en el NT es notable: una mina envuelta en un paño (Luke 19:20), la esperanza reservada en los cielos (Col 1:5), la corona de justicia guardada para Pablo (2 Tim 4:8) y el decreto divino de la muerte para toda la humanidad (Heb 9:27). El español distingue entre «reservado/reservada» para el sentido de tesoro guardado y «guardada» para custodia, aunque el verbo griego abarca ambos matices en un solo término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0607', 'spa', 'Decapitar; ejecutar cortando la cabeza', 'Verbo de significado sombrío y específico que denota cortar la cabeza a alguien, usado en el NT exclusivamente para la ejecución de Juan el Bautista. Las cuatro apariciones se agrupan en torno al mismo suceso narrado en los Evangelios Sinópticos (Matt 14:10; Mark 6:16, 27; Luke 9:9). La conciencia culpable de Herodes aflora en Mark 6:16 y Luke 9:9 cuando dice «a Juan, a quien yo decapité». El español emplea tanto «decapitó» (término clínico de origen latino) como «degolló» (cortar la garganta), revelando cómo los traductores distinguen entre la decapitación formal y la brutalidad visceral del acto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0609', 'spa', 'Cortar o cercenar físicamente; en voz media, mutilarse o castrarse. Se usa literal y figuradamente de la autoexclusión drástica.', 'Un verbo de separación violenta. En su uso más frecuente describe el acto de cortar algo con un instrumento afilado: Pedro cercenando la oreja de un siervo en Getsemaní (Jn 18:10, 18:26), la hipérbole radical de Jesús sobre cortarse la mano o el pie que hace tropezar (Mr 9:43, 45), y los marineros cortando las amarras del bote (Hch 27:32). Pero en Gálatas 5:12, Pablo emplea la voz media con mordaz sarcasmo, deseando que los agitadores de la circuncisión lleguen hasta el extremo de mutilarse a sí mismos, un impacto retórico que el español ''se mutilaran'' traduce con la fuerza reflexiva apropiada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0611', 'spa', 'Responder, contestar, replicar; dar una respuesta verbal, frecuentemente introduciendo discurso directo en la narración', 'El verbo ἀποκρίνομαι aparece 232 veces en el Nuevo Testamento, casi siempre en forma participial (ἀποκριθείς, ''habiendo respondido'') para introducir discurso directo. Mientras que el griego clásico lo empleaba para respuestas formales judiciales o deliberativas, el uso neotestamentario sigue un patrón hebraizante donde ''responder'' puede introducir un discurso incluso sin pregunta previa, significando simplemente ''comenzar a hablar en respuesta a una situación'' (Mt 11:25). Es la columna vertebral del diálogo evangélico, estructurando las conversaciones entre Jesús y sus discípulos, adversarios y multitudes. Las traducciones lo vierten uniformemente con su verbo estándar de réplica: español respondiendo, francés répondre, alemán antwortet.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0612', 'spa', 'Respuesta, réplica; contestación dada a una pregunta o desafío', 'En el griego clásico este sustantivo podía significar separación, secreción o incluso un tipo de danza, pero el NT lo emplea estrictamente en el sentido de una respuesta o réplica verbal. El niño Jesús asombró a los maestros con sus respuestas en el templo (Luke 2:47). En Luke 20:26, los adversarios enmudecieron, incapaces de sorprender a Jesús en su respuesta. John 1:22 registra a la delegación presionando al Bautista para obtener una respuesta definitiva sobre su identidad. El español «respuesta» confirma uniformemente el sentido de réplica conversacional a lo largo de todo el NT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0613', 'spa', 'Esconder, ocultar; mantener en secreto fuera del entendimiento o descubrimiento', 'Este verbo, que significa esconder u ocultar, lleva en el NT un peso teológico considerable: las verdades divinas están escondidas según el propósito soberano de Dios. Jesús alaba al Padre por haber escondido las realidades del reino de los sabios y haberlas revelado a los pequeños (Luke 10:21). Pablo habla de la sabiduría de Dios escondida desde antes de los siglos (1 Cor 2:7) y del misterio oculto por edades en Dios (Eph 3:9; Col 1:26). Las formas en participio perfecto pasivo subrayan que el ocultamiento fue deliberado y prolongado, hasta el momento señalado para la revelación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0614', 'spa', 'Oculto, secreto, escondido; lo que no es visible ni conocido, pero está destinado a ser revelado', 'Este adjetivo describe aquello que permanece oculto o guardado en secreto. Jesús enseña que nada hay «escondido» sino para ser manifestado, ni secreto sino para salir a la luz (Marcos 4:22; Lucas 8:17). Pablo habla de Cristo, en quien están «ocultos» todos los tesoros de la sabiduría y del conocimiento (Colosenses 2:3). El término puede referirse a una ocultación física o a la profunda reserva de los misterios divinos que van siendo desvelados. La tensión entre el ocultamiento presente y la revelación futura es central en su uso neotestamentario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0615', 'spa', 'Matar, dar muerte; en formas pasivas: ser muerto, asesinado o martirizado.', 'Uno de los verbos primarios del Nuevo Testamento para la violencia letal, ἀποκτείνω cubre todo el espectro desde el asesinato hasta la ejecución judicial y el martirio profético. Jesús advirtió a los discípulos que no temiesen a los que matan el cuerpo (Mt 10:28) y predijo repetidamente que sería muerto y resucitaría (Mt 17:23; Mr 8:31). Las formas pasivas revisten un peso teológico particular en las predicciones de la Pasión y en la representación de los testigos fieles inmolados por su testimonio en Apocalipsis. El español distingue con claridad el matar activo del ser muerto pasivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0616', 'spa', 'dar a luz, engendrar descendencia o producir resultados', 'Este verbo describe el acto de dar a luz o hacer surgir algo. En Santiago, aparece tanto en contexto biológico literal (el pecado dando a luz la muerte) como en contexto espiritual metafórico (Dios engendrando creyentes mediante la palabra de verdad). La evidencia multilingüe muestra una traducción consistente con lenguaje de nacimiento y generación en las lenguas romances y germánicas, reflejando el fundamento del término en la reproducción biológica aplicada teológicamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0617', 'spa', 'rodar, hacer rodar; quitar rodando (una piedra de la entrada de un sepulcro)', 'Un verbo sencillo pero inolvidable: hacer rodar algo para quitarlo. Todas las apariciones en el NT describen la remoción de la piedra que sellaba la tumba de Jesús en la mañana de la resurrección. Mateo 28:2 atribuye la acción a un ángel que rodó la piedra; Marcos 16:3-4 recoge la pregunta angustiada de las mujeres — «¿quién nos rodará la piedra?» — seguida del descubrimiento de que ya había sido rodada; y Lucas 24:2 simplemente señala que encontraron la piedra rodada. Las formas pasivas perfectas en Marcos 16:4 y Lucas 24:2 subrayan el estado consumado de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0618', 'spa', 'Recibir u obtener; recibir de vuelta lo perdido o adeudado; llevar aparte físicamente. En su núcleo, este verbo significa recibir de otro, pero el con', 'Recibir u obtener; recibir de vuelta lo perdido o adeudado; llevar aparte físicamente. En su núcleo, este verbo significa recibir de otro, pero el contexto determina si algo se obtiene por primera vez o se recupera. En Lucas 16:25, Abraham le dice al rico que ''recibió'' sus bienes en vida — una recepción inicial. Pero en Lucas 15:27, el padre ''recibió de vuelta'' a su hijo pródigo sano y salvo, enfatizando la restauración. El uso sorprendente en Marcos 7:33 — donde Jesús ''llevó aparte'' a un sordo de la multitud — desplaza el significado del intercambio económico al gesto físico. La evidencia multilingüe muestra que el francés y el alemán aplanan de manera similar la distinción entre recibir y recuperar, lo cual hace notable el matiz griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0619', 'spa', 'disfrute, la experiencia o resultado de disfrutar algo', 'Sustantivo que denota el acto de disfrutar o el placer derivado de algo. Pablo lo usa en 1 Timoteo 6:17 para describir la provisión divina de todas las cosas para nuestro disfrute, mientras que Hebreos 11:25 habla de Moisés rechazando el disfrute pasajero del pecado. El rango clásico incluye tanto la actividad de disfrutar como el beneficio concreto recibido. Los cuatro idiomas representados (inglés, español, francés, alemán) convergen en terminología de disfrute y placer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0620', 'spa', 'Dejar atrás, abandonar, desatender; intransitivo: permanecer, quedar, subsistir.', 'ἀπολείπω es un compuesto de ἀπο- (''lejos de'') y λείπω (''dejar''), con dos sentidos opuestos según la voz. En el uso activo transitivo significa dejar atrás: Pablo dejó su capa en Troas (2 Ti 4:13), dejó enfermo a Trófimo en Mileto (2 Ti 4:20) y dejó a Tito en Creta (Tit 1:5). Judas habla de ángeles que ''abandonaron'' su morada (Jud 1:6). Pero en la voz media-pasiva intransitiva el significado se invierte: algo ''queda'' o ''permanece''. Hebreos emplea este sentido para afirmar que un reposo sabático ''queda'' para el pueblo de Dios (Heb 4:9) y que no ''queda'' sacrificio para los que pecan deliberadamente (Heb 10:26).');